pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100 unknown,
    // but historically tiny gaps < 12 are near-useless) can fill are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }
    // Mid-range dead space (12..30) is mildly risky.
    if post_residual >= 12 && post_residual < 30 {
        score += 0.8 * (30.0 - post_residual as f64);
    }
    // Perfect or near-perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another gap: slight penalty proportional to the second gap.
        let second_gap = post_residual - next_item_size;
        if second_gap < 12 {
            score += 0.5 * (12.0 - second_gap as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // Many competing bins: prefer the tightest (already via post_residual), but add mild
    // pressure to close out bins when many are open.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins even more.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
        // Don't open a new bin when next item would fit the fresh bin too and bins are few.
        if next_item_size > 0 && open_bins_count < 3 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 48.0;
        } else if post_residual < 18 {
            score += 20.0;
        } else if post_residual < 35 {
            score += 5.0;
        }
    }

    // Strong 2-step lookahead: next item fitting into post residual is valuable,
    // tighter matches rewarded more.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 70.0 - slack * 0.6;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.9;
            if post_residual < 10 {
                score += 28.0;
            }
        }
    }

    // Combined coupling: exact two-item pairing — item plus next item exactly
    // fills the bin. Reward heavily to close bins early and avoid dead space.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 140.0;
    }

    // Tight-fit ratio: reward placements that consume a large fraction of the
    // residual, scaled by item size so big items closing bins win ties.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 13.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: attractive only when there is no alternative or it
    // serves the next item; otherwise heavily discouraged.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -32.0
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -24.0
        } else {
            90.0 + open_bins_count as f64 * 2.2
        };
        score += penalty;
    }

    // Residual balancing: prefer bins below mean residual, penalize far above.
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else if post_residual as f64 > mean_residual + 18.0 {
        score += (post_residual as f64 - mean_residual - 18.0) * 0.4;
    }

    // Progress-driven tightness: as the stream advances, favor bins that end
    // fuller (smaller post residual) slightly more, with early-phase boost to
    // build compact bins from the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = if progress < 0.15 { 0.17 } else { 0.11 * (1.0 + progress) };
    score -= (bin_capacity - post_residual) as f64 * tightness;

    // NEW: waste-ratio guard — placements leaving a post residual that no
    // typical next item could use (post residual too small relative to
    // capacity) are penalized proportionally, pushing toward near-closed bins.
    if post_residual > 0 && post_residual < bin_capacity / 8 {
        score += (bin_capacity / 8 - post_residual) as f64 * 0.9;
    }

    score
}

