    if post_residual >= 5 && post_residual <= 10 && progress > 0.5 && item_size >= post_residual / 2 {
        score -= 24.0 * progress;
    }

    // New-bin deferral — late in stream, strongly discourage fresh bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.6 {
        score += 60.0 * progress;
    }

    // Early-stream exploration — keep large residuals available.
    if progress < 0.3 && post_residual < 40 && item_size < 40 {
        score += 6.0;
    }

    // Reusability dead-space ratio scaled by progress.
    if post_residual > 0 && next_item_size > 0 {
        let reusability = if post_residual >= next_item_size { 0.0 }
            else if post_residual >= next_item_size / 2 { 8.0 }
            else { 20.0 };
        score += reusability * (0.5 + progress);
    }

    // Open-bin consolidation — many bins open: close hardest bins first.
    if open_bins_count > 4 && bin_residual < bin_capacity && post_residual > 0 {
        score += (post_residual as f64) * 0.06;
    }

    // Triple-fill lookahead — residual after next item matches a small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 25 && r2 >= item_size / 4 {
            score -= 12.0;
        }
    }

    // Divisibility harmony — clean multiples likely exactly filled later.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 || r % 5 == 0 {
            score -= 5.0;
        }
        if r > 50 && r % 25 == 0 {
            score -= 8.0;
        }
    }

    // Dead-space trap quantization — odd residuals that cannot split evenly
    // and cannot host the next item are prime waste; scale penalty by progress.
    if post_residual > 0 && post_residual < bin_capacity {
        let half_split_possible = post_residual >= 2 && (post_residual / 2) * 2 == post_residual;
        let next_closes = next_item_size > 0 && post_residual >= next_item_size;
        if !half_split_possible && !next_closes {
            score += 7.0 * (0.5 + progress);
        }
    }

    // Mean-residual gap targeting — steer post residual toward the fleet mean
    // to improve future combinability across bins.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should never leave a mid-band residual.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — keep scarce bins most reusable.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — final stretch, any nonzero residual is nearly pure waste.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space-ratio quadratic refinement fused with slack-sharpness gradient.
    if post_residual > 0 {
        let dr = post_residual as f64 / bin_capacity as f64;
        let hostable = next_item_size > 0 && post_residual >= next_item_size;
        let small_hostable = post_residual <= 12;
        if !hostable && !small_hostable {
            score += dr * dr * 60.0 * (0.4 + progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 / (1.0 + slack * 0.35)) * 20.0 * (0.5 + progress);
    }

    // Near-closure trap guard fused with residual-band reusability.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 6 {
        score += 25.0 + 20.0 * progress;
    }
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 7 == 0)
        && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Lookahead tight-fit coupling with scarcity amplification.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 18.0;
        }
    }

    // NEW: dead-space variance squeeze — modular residue class alignment.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // NEW: lookahead-scarcity coupling for large next items.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // NEW: perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // NEW: residual-combinability index — reward post residuals expressible
    // as sums of two common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
        if combinable {
            score -= 7.0 * (0.5 + progress);
        }
    }

    // NEW: slack-variance squeeze — when several bins fit, sharpen preference
    // toward the bin whose post residual best matches the mean residual,
    // reducing fleet-wide residual variance (dead space).
    if fitting_bins_count > 2 && post_residual > 0 && bin_residual < bin_capacity {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.10 * progress;
    }

    // NEW: triple-fill exact anticipation — current + next leaves a residual
    // equal to a plausible third item (half of next), enabling full closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // NEW: new-bin gating refinement — when a fresh bin would be opened but
    // the item fits with near-zero slack in an existing bin, block new bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if item_size >= 90 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can fill are worthless.
    // Penalize unusable gaps super-linearly (items >= 10 traditionally, but unknown dist: use soft threshold).
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Gap too small to ever be used -> heavy penalty proportional to wasted capacity.
        score += (dead_threshold - post_residual as f64) * 4.0;
    } else {
        // Usable gap: mild reward for tighter fit, scaled by how well next item may slot in.
        score -= 2.0;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 3.0; // lookahead fits exactly into the gap: strongly favor
        }
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is a dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if (post_residual as f64) >= dead_threshold {
            score -= 8.0;
        }
    }

    // New-bin candidate: neutral baseline; open a fresh bin only when all fits are bad.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.2;
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Stream progression: slightly more willing to fill existing bins tightly later on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter coupling: reward exact/near matches much more.
            if slack == 0.0 {
                score -= 120.0;
            } else if slack <= 5.0 {
                score -= 80.0 - slack * 4.0;
            } else {
                score -= 30.0 - slack * 0.3;
            }
        } else {
            // Dead space for the next item: penalize the unusable gap,
            // but soften the penalty when the gap is large enough that
            // some future item could still land there.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.9;
            if post_residual < 8 {
                score += 35.0;
            } else if post_residual < 15 {
                score += 15.0;
            }
        }
    }

    // Residual balance: discourage creating outliers above the mean.
    let pr = post_residual as f64;
    if pr > mean_residual + 15.0 {
        score += (pr - mean_residual - 15.0) * 0.35;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // forced: no alternative
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin can hold current + next item: only prefer it when
            // the alternative fit was loose (poor compaction elsewhere).
            let tight_alt = fitting_bins_count <= 2
                && (bin_capacity - item_size) as f64 <= mean_residual + 10.0;
            if tight_alt {
                score += 20.0;
            } else {
                score -= 25.0;
            }
        } else {
            // Discourage scattering, scaled with how many bins are open.
            score += 80.0 + open_bins_count as f64 * 2.5;
        }
    }

    // Progressive compaction pressure: fill tightly as the stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.12 * progress;

    // Late-stream: prefer closing bins completely to reduce open-bin count.
    if progress > 0.8 && post_residual < 20 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that cannot fit the next item (wasted capacity).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 {
        // Reward bins that can also host the lookahead item.
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Coupling with global state: prefer bins below mean residual when many bins open.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.05;

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let base = 30.0 + item_size as f64 * 0.6;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a new bin keeps room for the similar/larger next item.
            score = base - 10.0;
        } else {
            score = base;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

