        } else {
            85.0 + open_bins_count as f64 * 2.0
        };
        score += penalty;
    }

    // Residual balancing: prefer bins below mean residual, penalize far above.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else if post_residual as f64 > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual - 20.0) * 0.35;
