    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: exact fit (0), tiny waste, medium dead space, large usable
    let class: f64 = if post_residual == 0 {
        -12.0 // perfect closure
    } else if post_residual <= 10 {
        -6.0 // near-perfect, nearly unusable anyway
    } else if post_residual <= 25 {
        4.0 // dead space: too small for most items
    } else if post_residual <= 50 {
        0.0 // medium
    } else {
        -2.0 // large residual, still flexible
    };
    score += class;

    // Integer-division thresholds: waste quantized by typical item granularity
    let dead = post_residual / 10; // how many 10-sized items cannot be replaced
    score += dead as f64 * 1.5;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post);
        } else {
            // next item won't fit here; penalize leaving residual it can't use
            score += (next_item_size as f64 - post) / cap * 8.0;
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish but penalize if open bins exist with good fits
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Progress: early on, be frugal with bins; late, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 - progress * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: penalize placements that diverge from fleet state
    score += (post - mean_residual).abs() * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: any residual < 10 can never fit another item.
            score += 60.0;
        } else if post_residual <= 25 {
            // Small gap: only fits very small future items; heavy penalty scaled by gap smallness.
            score += (25.0 - post_residual as f64) * 1.8;
        } else if post_residual >= 40 {
            // Healthy residual that can still absorb typical items: reward.
            score -= 12.0;
        }
    } else {
        // Perfect fit: strongly reward closing a bin.
        score -= 100.0;
    }

    // Perfect-fit lookahead: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // Open-bin pressure: penalize spreading across many bins; encourage filling existing ones.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when residuals are large and unusable, or no open bin is tight.
    if bin_residual == bin_capacity {
        // Base new-bin cost rises with number of open bins (discourage bin proliferation).
        score += 25.0 + open_bins_count as f64 * 4.0;
        // Late in the stream, opening new bins is cheaper than wasting space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
    }

    // Prefer bins tighter than the average residual (better fit quality).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Mild reward for bins whose residual matches item size well (low waste fraction).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly fills the post_residual (perfect chain), mildly when it fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 60.0;
        } else {
            // Next item cannot use this residual: penalize leftover space
            // proportionally to how unusable it is for the next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Reward placing into below-mean-residual bins (tight packing),
    // penalize dipping into bins with more room than average.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.3 * post_residual as f64;
        // Allow new-bin opening late in the stream only if nothing fits well.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Late-stream pressure: consolidate bins as the stream ends.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 45.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize leaving residuals that are too small to be useful later
    // (dead space zone: residual < 10 or residual < next_item_size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * next_item_size as f64;
    }

    // Lookahead synergy: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: when many bins are open, discourage opening new ones;
    // a fresh empty bin (bin_residual == bin_capacity) gets penalized more
    // as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap; later it is costly.
        score += 20.0 * progress;
    } else {
        // Mild reward for filling existing bins when bin count is high.
        score -= 2.0 * open_bins_count as f64 * (1.0 - tight);
    }

    // Prefer bins whose residual is below the mean (fill the emptiest-relative bins less,
    // keep balanced residuals): penalize bins far above mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight noise-free tie-breaker scaled by item size: prefer placing larger items
    // into bins with larger current residual (best-fit-like behavior).
    score += 0.05 * item_size as f64 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over progress
    let mut score = pr;

    // Smooth polynomial coupling: residual value changes with stream progress.
    // Early: waste is more tolerable (favor tight fits less strictly);
    // Late: dead space is costly, so amplify residual penalty quadratically.
    let progress_coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * progress_coupling * cap * 0.01;

    // Cubic interaction: very small residuals become premium late in stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // and when open bins exist that could fit; relax slightly late if residual tiny.
    if bin_residual == bin_capacity {
        let open_bias = open_bins_count as f64;
        let new_bin_penalty = 45.0 + 25.0 * (1.0 - progress) + 2.0 * open_bias;
        // If lookahead item is large, a fresh bin is more attractive (smooth term)
        let lookahead_relief = (next_item_size as f64 / cap) * 20.0;
        score = new_bin_penalty - lookahead_relief;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < f64::EPSILON {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // next item fits: mild reward proportional to fit quality
        score -= 10.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item won't fit here: penalize leaving awkward gap
        score += 8.0 * norm_pr;
    }

    // Mean residual deviation: prefer bins whose residual deviates from the mean
    // (keeps a spread of residual sizes for future items) — smooth quadratic term
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap * 0.1;

    // Small penalty for very many open bins to discourage fragmentation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in (0,10] is worst.
    let pr = post_residual;
    if pr > 0 {
        if pr <= 10 {
            score += 30.0; // tiny unusable sliver
        } else if pr <= 20 {
            score += 10.0;
        } else {
            // quantized penalty by residue class modulo 10
            let class = pr % 10;
            score += 4.0 + class as f64 * 0.5;
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + slack * 0.05; // chain-friendly bin
    } else if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
        score += 6.0; // next item will need another bin anyway
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it slightly attractive unless an open bin fits well.
    if bin_residual == bin_capacity {
        score -= 12.0 - (open_bins_count as f64).min(20.0) * 0.3;
    }

    // Prefer bins below mean residual (use emptier bins first, keep tight bins for small items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals that are too small to ever fit the minimum item size (1)
    // are pure waste; residuals just below typical item sizes are worst.
    let pr = post_residual as f64;
    if pr == 0.0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if pr < 10.0 {
        // Tiny unusable gap: heavy penalty.
        score += 25.0 - pr;
    } else if pr < 30.0 {
        // Small gap: usable only by small items; moderate penalty.
        score += 8.0 - 0.2 * pr;
    } else {
        // Large residual is flexible: mild discount relative to raw value.
        score -= 0.15 * pr;
    }

    // --- Tight-fit reward: fraction of bin consumed by this placement ---
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, be pickier about dead space (amplify penalties).
        if pr > 0.0 && pr < 10.0 {
            score += 10.0;
        }
    }

    // --- Open-bin pressure: discourage scattering across many bins,
    //     but only when the stream is early/mid (future items still benefit
    //     from a healthy spread of residuals). ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln_1p() * (1.0 - progress);
    score += 3.0 * pressure;

    // --- Mean residual coupling: if this bin's residual is far below the mean,
    //     it is already "cramped"; prefer consolidating into cramped bins so
    //     roomy bins stay available for large future items. ---
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // --- Lookahead: if the next item fits exactly in the post residual,
    //     reward leaving that gap; if next item is large and this bin would
    //     be left with a useless small gap, penalize. ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr && pr - nxt < 10.0 {
            // Perfect setup for the next item.
            score -= 12.0;
        } else if pr > 0.0 && pr < nxt && pr < 10.0 {
            // Dead space that the known next item cannot use.
            score += 6.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh bin has full flexibility: base appeal, but add pressure so
        // it only wins when all open alternatives have poor (dead-space) fits.
        score = 45.0 + 2.0 * (open_bins_count as f64).ln_1p() * (1.0 - progress);
        // If the item is large relative to capacity, opening fresh is cheap insurance.
        if fill_frac > 0.6 {
            score -= 5.0;
        }
        // If the only alternative is a tiny dead-space gap, make new bin more appealing
        // is handled implicitly: open bins with pr<10 got large penalties.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward, stronger when the match is tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Dead space for the next item: penalize proportionally to unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
            // Very small unusable leftovers are the worst.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Compare post residual against mean residual across open bins.
    // Keeping residuals balanced avoids many half-full bins.
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual - 20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -30.0 // forced: no alternative
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -20.0 // fresh bin accommodates the next item too
        } else {
            80.0 + open_bins_count as f64 * 2.0 // discourage scattering
        };
        score += penalty;
    }

    // Slight preference for filling bins tightly as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Perfect chaining: post residual exactly matches next item size.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global state: when many bins are open, prefer consolidation.
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (1.0 - tightness);

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (fill fuller bins first), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let deviation = mean_residual - bin_residual as f64;
    score += 0.3 * deviation * (0.5 + progress);

    // New-bin candidate handling: only attractive when item is huge relative
    // to capacity or no good fits exist; penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if big_item > 0.7 {
            score -= 5.0 * big_item;
        } else {
            score += 35.0 + 20.0 * (1.0 - progress);
        }
    }

    // Late stream: tighten everything, discourage waste more aggressively.
    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, non-linearly shaped by stream progress.
    let mut score = pr;

    // Smooth polynomial coupling: early on, prefer tight fills (low post_residual);
    // later, dead space matters more, so amplify quadratic term with progress.
    let quad = x * x * (200.0 + 600.0 * progress);
    let cube = x * x * x * (300.0 * progress * progress);
    score += quad + cube;

    // Reward near-perfect fits (post_residual close to 0) with smooth bonus.
    score -= 40.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: smooth reward when the next item fits the resulting residual.
    let nxs = next_item_size as f64;
    if nxs > 0.0 {
        let fit_gap = (pr - nxs).abs();
        let fit_norm = fit_gap / cap;
        score -= 30.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: smooth penalty for opening new bins when few fit options exist.
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty coupling with mean residual: avoid worsening an already-fragmented fleet.
    let mr = mean_residual / cap;
    score += 20.0 * mr * x * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets neutral-ish score with progress-dependent bias.
    if bin_residual == bin_capacity {
        score = cap - 60.0 * (1.0 - progress) * (1.0 - progress) + 15.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions matter.
    // A residual that is a "nice" fraction of capacity (0, 25, 50, 75) is reusable.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let harmonic_bonus = if post_residual == 0 {
        -40.0 // perfect fit
    } else if post_residual % quarter == 0 {
        -12.0
    } else if post_residual % 10 == 0 {
        -6.0
    } else if post_residual < 10 {
        25.0 // dead space: too small for any item
    } else {
        0.0
    };
    score += harmonic_bonus as f64;

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact / near-exact chain fit is very desirable
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 10.0 * (slack / cap);
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize small leftover more
            score += 6.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; relax late in stream or when
        // mean residual across open bins is small (fragmented bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let penalty = 30.0 - 15.0 * fragmentation - 10.0 * progress;
        // small items justify a fresh bin less
        score += penalty + 0.2 * item_size as f64;
        // if next item is huge, a fresh bin is more attractive
        if next_item_size > half {
            score -= 10.0;
        }
    }

    // Integer-division threshold on post_residual: buckets of 20
    let bucket = post_residual / 20;
    score -= bucket as f64 * 2.0; // prefer bins with larger coarse buckets

    // Slight preference for tighter fits overall (best-fit core)
    score += (bin_residual - post_residual) as f64 * 0.0; // no-op anchor

    // Tie-break: prefer bins whose residual is close to item size class
    let item_class = item_size / 10;
    let res_class = bin_residual / 10;
    if item_class == res_class {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable dead space (items >= 10 in original regime; be cautious generally)
            score += 60.0 * (1.0 - gap / 10.0);
        } else if gap < 20.0 {
            // Likely unusable for most items: strong penalty
            score += 25.0 * (1.0 - gap / 20.0);
        } else {
            // Usable residual: mild reward scaled by size
            score -= 0.15 * gap;
        }
    } else {
        // Perfect fit: big reward
        score -= 80.0;
    }

    // Dead-space penalty amplified when gap can't hold the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward if lookahead fits exactly in the post residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is poor
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins are very full / poor fits
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 + 40.0 * avg_tightness;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Prefer bins tighter than average (better packing)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: tight fit now (small post_residual rewarded).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 45.0 * (1.0 - tightness).powi(3);

    // Perfect fit for the NEXT item: post_residual exactly matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // chain a perfect 2-step packing
        } else if post_residual >= next_item_size {
            // next item fits here too; reward small leftover after both
            let both = (post_residual - next_item_size) as f64;
            score -= 55.0 * (1.0 - both / bin_capacity as f64);
        } else {
            // next item CANNOT fit here: penalize wasted residual that becomes dead space
            score += 18.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Relative to mean residual: placing into a bin with residual near the mean
    // keeps flexibility; extreme residuals are penalized slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.12 * dev;

    // New-bin candidate (empty bin): penalize so we only open when all fits are bad.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Opening a new bin is more attractive late in the stream or when few bins fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0; // fresh bin can also host the next item
        }
        if fitting_bins_count == 0 {
            score -= 90.0; // no open bin fits: must open
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early phase favors keeping options open, late phase favors tight packing.
    let t = step_index as f64 / total_items.max(1) as f64;

    // Penalize large post-residual more strongly as stream progresses (dead space matters more later).
    score += (post_residual as f64 / bin_capacity as f64) * (post_residual as f64) * (0.5 + t);

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Post-residual becomes dead space if next item can't use it and it's small.
            if post_residual < 10 {
                score += 8.0;
            }
        }
        // Perfect future fill: residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, penalize mediocre fits.
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Global state coupling: when mean residual across bins is low (bins nearly full),
    // favor filling existing bins tightly; when mean residual is high, opening new bins
    // is less costly, so be less desperate.
    let mean_r_norm = mean_residual / bin_capacity as f64;
    score -= (1.0 - mean_r_norm) * 5.0;

    // Prefer bins that are already substantially filled (consolidation heuristic),
    // stronger early when many bins are open.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (4.0 + open_bins_count as f64 * 0.3) * (1.2 - t);

    // Slight penalty for opening a new bin when plenty of open bins exist with room.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5 - mean_r_norm * 10.0;
        // But new bin is attractive if it enables a perfect two-item schedule.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Exact fit celebration.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_n = pr / c;

    // Smooth non-linear polynomial coupling of post-residual with stream progress
    let mut score = pr_n * (1.0 + 0.6 * progress + 0.8 * pr_n * progress);

    // Reward tight fits: cubic decay of penalty as post-residual shrinks
    score -= 2.5 * (1.0 - pr_n).powi(3) * (1.0 - progress);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = ((pr - nx) / c).max(0.0);
        score += 1.8 * waste * waste * (0.5 + progress);
        // Reward bins whose post-residual exactly accommodates next item
        if nx <= pr {
            score -= 0.8 * (1.0 - ((pr - nx) / c));
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Mildly prefer opening new bins when many bins are open and mean residual is large
    score += 0.3 * (open_bins_count as f64 / (mean_residual / c + 1.0)) * 0.1;

    // New-bin candidate: neutral-ish score that competes only against bad fits
    if bin_residual == bin_capacity {
        score = c * (0.35 + 0.25 * progress) - 0.5 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on
    // "friendly" residues (multiples of 10, or >= next item) are favored.
    let pr = post_residual;
    let residue_class = pr % 10;

    // Penalize awkward dead space (residues 1..9 that are hard to fill).
    if pr > 0 && residue_class != 0 {
        score += (10 - residue_class) as f64 * 0.8;
    }

    // Reward exact/waste-free fits strongly.
    if pr == 0 {
        score -= 30.0;
    }

    // Harmonic compatibility: can the lookahead item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: leftover exactly matches next item.
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                // Fractional chain quality: smaller gap after next placement is better.
                let gap_after_next = post_residual - next_item_size;
                score -= 12.0 * (1.0 - gap_after_next as f64 / cap);
            }
        } else {
            // Leftover too small for next item: dead space penalty scaled
            // by how "wasted" it is relative to next item size.
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Integer-division threshold on post_residual: classify leftover zones.
    let zone = pr / 25; // 0: tiny, 1: small, 2: medium, 3: large
    match zone {
        0 => {
            if pr > 0 { score += 8.0; } // tiny leftovers are nearly dead space
            else { score -= 30.0; }
        }
        1 => { score += 2.0; }
        2 => { score -= 3.0; } // medium leftovers are reusable
        _ => { score -= 5.0; } // large leftovers very reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40 || (fitting_bins_count == 0);
        if poor_fit {
            score -= 10.0;
        } else {
            score += 20.0 + 0.1 * mean_residual; // prefer existing bins
        }
    }

    // Late in the stream, tighten packing (less tolerance for slop).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect closure: dominant reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 6.0; // near-perfect, nearly unusable anyway
    } else if post_residual <= 25 {
        score += 4.0; // dead space
    } else if post_residual <= 50 {
        score += 0.0;
    } else {
        score -= 2.0;
    }

    // Waste quantization
    score += (post_residual / 10) as f64 * 1.5;

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tight match strongly rewarded; loose match mildly rewarded
            score -= 40.0 - slack * 0.4;
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if post_residual < 10 {
                score += 20.0; // tiny unusable leftovers are the worst
            }
        }
    } else {
        score -= 10.0; // last item: prefer closing bins
    }

    // Last-chance bin: strongly avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // forced: no alternative
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin accommodates next item too
        } else {
            score += 80.0 + open_bins_count as f64 * 2.0; // discourage scattering
        }
    }

    // Progress: consolidate more as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    // Mean residual coupling
    score += (post - mean_residual).abs() * 0.03;

    score
}

