    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // COMBINED REFINEMENT: two-step compaction chain — reward placements where
    // the next item fits and the leftover after it is exactly reusable by a
    // small plausible item (item_size/2 band), merging lookahead with
    // fine-grained residual fitting to cut dead space.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 {
            if item_size >= r2 || r2 % 5 == 0 {
                score -= 16.0;
            }
        } else if r2 > 25 {
            score += (r2 as f64 - 25.0) * 0.3;
        }
    }

    // COMBINED REFINEMENT: mean-residual convergence — prefer post residuals
    // close to the mean residual so future items of typical size still fit.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        if drift < 10.0 {
            score -= (10.0 - drift) * 0.9;
        } else if drift > 30.0 {
            score += (drift - 30.0) * 0.35;
        }
    }

    score
}

