    }

    // REFINED: next-item stranding guard — if placing the item here leaves a
    // residual that the next item cannot fit but another open bin's residual
    // could, mildly prefer the alternative (avoid creating dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
