    // item cannot use and that exceed half of the mean residual, add a
    // quadratic penalty so large dead zones are avoided decisively.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) > mean_residual * 0.5 {
