pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);

        // strong bonus for perfect sequential fit
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // penalize leaving space that next item cannot use at all
        if post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: just minimize leftover waste
        score += 0.5 * post_residual as f64;
    }

    // penalize creating tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // relative to mean residual: prefer bins that tighten the average
    score += 0.4 * (post_residual as f64 - mean_residual);

    // last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // new empty bin candidate: penalize so it's chosen only when fits are bad,
    // but less so when item is large or few bins fit it
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 70.0 - 30.0 * scarcity - 0.2 * item_size as f64;
    }

    // mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 110.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 55.0;
        } else if post_residual < 18 {
            score += 22.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.7;
            if slack <= 3 {
                score -= (4.0 - slack) * 7.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.0;
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 170.0;
    }

    // Tight-fit ratio: reward placements consuming a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 16.0;
    }

    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.9;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: attractive only when no alternative exists.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -35.0
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -25.0
        } else {
            100.0 + open_bins_count as f64 * 2.2
        };
        score += penalty;
    }

    // Residual balancing: prefer bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else if post_residual as f64 > mean_residual + 18.0 {
        score += (post_residual as f64 - mean_residual - 18.0) * 0.4;
    }

    // Progress-driven tightness.
    let tightness = if progress < 0.15 { 0.18 } else { 0.11 * (1.0 + progress) };
    score -= (bin_capacity - post_residual) as f64 * tightness;

    // Chain potential: post residual can host next item with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        if chain_slack > 0 && chain_slack <= 12 {
            score -= 14.0;
        }
    }

    // Anti-fragmentation: residual equal to item size stays reusable.
    if post_residual > 0 && post_residual == item_size {
        score -= 20.0;
    }

    // Awkward-residual trap: 20-45 band unusable by next item.
    if post_residual >= 20 && post_residual <= 45 && next_item_size > post_residual {
        score += 12.0;
    }

    // Late-stream consolidation: fill existing bins almost completely.
    if progress > 0.7 && post_residual > 0 && post_residual < 25 {
        score -= 9.0 * progress;
    }

    // Graded near-perfect band late in stream.
    if post_residual >= 5 && post_residual <= 10 && progress > 0.5 && item_size >= post_residual / 2 {
        score -= 24.0 * progress;
    }

    // Exact-pair anticipation: two identical items exactly fill the bin.
    if next_item_size > 0 && next_item_size == item_size && item_size * 2 == bin_residual {
        score -= 45.0;
    }

    // Mid-stream selection sharpening: many fitting bins -> prefer emptiest.
    if fitting_bins_count > 2 && bin_residual < bin_capacity {
        score += (bin_residual as f64) * 0.05;
    }

    // Reusable-residual harmony — post residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 24.0;
    }

    // Small-item sink — tiny items go into the smallest usable gap.
    if item_size <= 10 && post_residual > 0 && post_residual < 30 {
        score -= 16.0;
    }

    // Dead-zone guard — 46-60 band hard to fill.
    if post_residual >= 46 && post_residual <= 60 && next_item_size > post_residual {
        score += 15.0;
    }

    // Three-step viability — post residual hosts next item leaving a small residual.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 12 && next_item_size >= r2 {
            score -= 10.0;
        }
    }

    // Avoid leaving residuals in the 61-99 band when next item cannot use them.
    if post_residual >= 61 && post_residual <= 99 && next_item_size > post_residual {
        score += (post_residual as f64 - 60.0) * 0.35;
    }

    // Early-stream exploration: keep large residuals available.
    if progress < 0.3 && post_residual < 40 && item_size < 40 {
        score += 6.0;
    }

    // Residual divisibility harmony — clean multiples likely exactly filled later.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 || r % 5 == 0 {
            score -= 5.0;
        }
        if r > 50 && r % 25 == 0 {
            score -= 8.0;
        }
    }

    // Pair-sum anticipation — next item plus current exactly fills residual.
    if next_item_size > 0 && next_item_size + item_size == post_residual {
        score -= 18.0;
    }

    // Many-fitting-bins tightness — best-fit sharpening when alternatives abound.
    if fitting_bins_count > 3 && bin_residual < bin_capacity {
        score -= (bin_capacity - post_residual) as f64 * 0.03;
    }

    // Late-stream zero-waste push — closing bins matters more near the end.
    if progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64) * 0.25;
    }

    // Residual-halving chain — post residual exactly half of bin residual
    // implies a second identical item could close the bin; strong compaction cue.
    if post_residual > 0 && post_residual * 2 == bin_residual {
        score -= 22.0;
    }

    // Capacity-scaled waste pressure — as progress grows, penalize any
    // leftover residual proportionally, forcing tighter fills mid/late stream.
    if post_residual > 0 {
        score += (post_residual as f64) * 0.08 * progress;
    }

    // Exact post-residual reusability — reward when the post residual can
    // exactly host any small future item (residual in common small-item band).
    if post_residual > 0 && post_residual <= 12 && progress > 0.35 {
        score -= 18.0;
    }

    // Dead-space ratio penalty scaled by how few bins can still use this
    // residual band — residuals near item sizes are reusable, others are waste.
    if post_residual > 0 && next_item_size > 0 {
        let reusability = if post_residual >= next_item_size { 0.0 }
            else if post_residual >= next_item_size / 2 { 8.0 }
            else { 20.0 };
        score += reusability * (0.5 + progress);
    }

    // Triple-fill lookahead — reward when item + next item leaves a residual
    // that matches a plausible small item (quarter-capacity band).
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 25 && r2 >= item_size / 4 {
            score -= 12.0;
        }
    }

    // Open-bin consolidation — when many bins are open, prefer the bin
    // whose post residual is closest to zero (hardest bin to close first).
    if open_bins_count > 4 && bin_residual < bin_capacity && post_residual > 0 {
        score += (post_residual as f64) * 0.06;
    }

    // New-bin deferral — late in the stream, opening a new bin should be
    // strongly discouraged unless the item cannot fit anywhere.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.6 {
        score += 60.0 * progress;
    }

    // REFINED: dead-space ratio — penalize residuals that neither the next item
    // nor any plausible item band can absorb, weighted by how much of the
    // capacity remains stranded. Targets the diagnosed dead-space weakness.
    if post_residual > 0 {
        let stranded = post_residual as f64 / bin_capacity as f64;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        let reusable_band = post_residual <= 12 || post_residual % 5 == 0;
        if !usable_by_next && !reusable_band {
            score += stranded * 45.0 * (0.6 + progress);
        }
    }

    // REFINED: fit-margin sharpening — when the item nearly exactly fills the
    // bin residual (slack <= 5), reward progressively harder, since near-exact
    // fits minimize the residual variance observed in the parent profile.
    if post_residual > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        if slack <= 5 {
            score -= (6.0 - slack as f64) * 6.0;
        }
    }

    // REFINED: next-item stranding guard — if placing the item here leaves a
    // residual that the next item cannot fit but another open bin's residual
    // could, mildly prefer the alternative (avoid creating dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
