    // valuable if some plausible item size can land in it exactly or with tiny
    // slack. Reward residuals that divide cleanly by small item sizes, punish
    // residuals that are 1-3 away from a half/quarter capacity anchor (the
    // most common near-miss dead zones observed in the parent profile).
    if post_residual > 0 {
        let r = post_residual;
        let mut granularity_bonus = 0.0;
        for anchor in [1u32, 2, 4, 5, 10, 20, 25, 50] {
            if r % anchor == 0 {
                granularity_bonus += 3.0;
            }
        }
        score -= granularity_bonus * (0.4 + progress);
        // Near-miss dead zones: r just below a highly-usable size implies
        // stranded slack that no item can absorb.
        for anchor in [25u32, 30, 34, 50, 60, 75] {
            if r < anchor && anchor - r <= 3 {
                score += (4.0 - (anchor - r) as f64) * 5.0;
            }
        }
    }

