    // a plausible companion (half of remaining residual) fit, i.e. the bin can
    // be closed in exactly two more steps. Sharpened by progress.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 > 0 && r2 % 2 == 0 && r2 / 2 <= 30 {
            score -= 8.0 * (0.5 + progress);
        }
    }

