    // open bins offer only poor fits (post residual would exceed half the
    // capacity), tilt toward opening a fresh bin early in the stream where
    // future items are more likely to fill it; late, prefer any fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if progress < 0.45 {
            score -= 12.0 * (0.45 - progress);
        } else {
            score += 10.0 * (progress - 0.45);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += 0.6 * (post_residual as f64 / cap).powi(2) * cap;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 12.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 2.0 * (post_residual as f64 / cap);
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin when reasonable alternatives exist,
    // but allow it when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = post_residual as f64; // residual of a fresh bin = cap - item
        let open_bin_waste = mean_residual - item_size as f64;
        score += 8.0 + 6.0 * progress;
        if open_bin_waste < waste * 0.5 {
            score += 10.0; // an open bin wastes much less; keep using it
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative at all: must open
        }
    }

    // Mild preference for bins whose residual deviates from the mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight bonus for filling bins fuller as the stream progresses.
    let fill_ratio = 1.0 - (post_residual as f64 / cap);
    score -= 3.0 * fill_ratio * (step_index as f64 / (total_items.max(1) as f64));

    score
}

