    // REFINED: fit-margin sharpening — near-exact fits minimize residual variance.
    if post_residual > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        if slack <= 5 {
            score -= (6.0 - slack as f64) * 6.0;
        }
    }

    // REFINED: next-item stranding guard.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // NEW: dead-space elimination coupling — when the item leaves a residual that
    // the next item can almost exactly absorb (slack 1-6), treat the bin as
    // effectively closed; this directly attacks residual dead space.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 <= 6 {
            score -= (7.0 - slack2 as f64) * 9.0 * (0.5 + progress);
        }
    }

    // NEW: residual-size trap sharpening — residuals just under a "typical" item
    // size (just below next item or just below half capacity) are the worst
    // dead space; penalize the near-miss band more precisely.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size - post_residual <= 8 {
        score += (next_item_size - post_residual) as f64 * 2.5 + 8.0;
    }

    // NEW: capacity-aware compaction — when few bins fit and the item consumes
    // more than 80% of the residual, push hard toward that bin (best-fit with
    // fill-rate coupling), reducing scatter of near-full bins.
    if bin_residual < bin_capacity && item_size * 5 >= bin_residual * 4 {
        score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // NEW: late-stream new-bin lockout refinement — a fresh bin late is only
    // acceptable if the item is large (would waste > 40% of an existing bin).
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.45 {
        let best_possible_waste = fitting_bins_count as f64;
        let _ = best_possible_waste;
        if item_size < 60 {
            score += 35.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize post-residual, but weight it non-linearly by stream progress.
    // Early on, small residuals matter less; late, tight packing is crucial.
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 2.5 * progress * progress);

    // Smooth non-linear coupling: reward filling the bin tightly (quadratic in fill ratio)
    let fill = it / (bin_residual as f64);
    score -= 1.8 * fill * fill;

    // Cubic interaction: dead space near mid residuals is worst
    score += 0.9 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 0.6 * (1.0 - (pr - n) / cap);
        } else {
            score += 0.3 * ((n - pr) / cap);
        }
    }

    // Prefer bins tighter than the mean residual (smooth term)
    score += 0.4 * ((bin_residual as f64) - mean_residual) / cap;

    // New-bin candidate: mild penalty so it only wins when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 0.8 + 1.5 * progress;
    }

    score
}

