pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity/4 bands.
    // Items in the same harmonic band are "compatible" partners; a post_residual
    // that lands exactly on a band boundary is a premium fit.
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter; // 0..4 harmonic class
    let band_edge = post_residual % quarter == 0 && post_residual > 0;

    // Reward post_residuals that are likely reusable by typical item sizes:
    // small residuals (< 10) are dead space -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    }

    // Reward band-edge residuals (e.g. 25, 50, 75) - highly reusable.
    if band_edge {
        score -= 12.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this is a harmonic pairing -> strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: penalize proportionally to leftover dead space
        let next_left = post_residual - next_item_size;
        if next_left < 10 {
            score -= 20.0;
        } else {
            score -= (next_left as f64) * 0.3;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; slight penalty scaled by gap
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Congestion pressure: many open bins with large mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 8.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): baseline score equals
    // full capacity minus a discount that grows when existing bins are bad fits.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) - 10.0;
        // Open a new bin only if the item is large and no tight alternative exists.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // pairing impossible anyway; new bin slightly less attractive
            score += 5.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer closing out
    // bins with small residuals (harmonic class 0 band).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if band == 0 && post_residual > 0 {
        score -= 10.0 * progress;
    }

    score
}

