        }
    }

    // NEW: large-item bin conservation — big items should not burn bins whose
    // residual is small enough to be closed by a small item later.
    if item_size > bin_capacity / 2 && bin_residual < bin_capacity && post_residual > 0 && post_residual <= 20 {
        score += 10.0;
    }

    // NEW: sharpened new-bin gate — a fresh bin is only attractive when the
    // next item is large relative to what any open residual could chain.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        if next_item_size > bin_capacity / 3 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // Dead space penalty grows as gap shrinks toward 0 (most useless).
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Moderate fits: reward tightness mildly.
        score -= (bin_residual - post_residual) as f64 * 0.05;
    }

    // Reward bins whose residual matches the next item size (lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        score -= (20.0 - diff.min(20) as f64) * 1.5;
    }

    // Open-bin pressure: penalize creating many open bins, but only mildly,
    // so dead-space avoidance still dominates.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when all
    // open bins have bad fits. Make it slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in the stream, opening bins is cheaper (fewer bins committed).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
    }

    // Slight preference toward bins below mean residual (fill emptier bins
    // less; prefer denser bins to consolidate).
    if (bin_residual as f64) > mean_residual {
        score += 1.5;
    }

    score
}

