    // next item cannot use and that are not multiples of 5 are the largest
    // source of stranded capacity; penalize proportionally to open-bin count
    // to force consolidation into fewer, tighter bins.
    if post_residual >= 31 && post_residual <= 45 && next_item_size > post_residual && post_residual % 5 != 0 {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    // NEW (gen 13): large-item hoarding guard — when the current item is large
    // (> half capacity) and it fits an existing bin, opening a new bin is
