    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if post-residual is just barely below next item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when open bins
    // are crowded (low mean residual) or the item fits nothing well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 25.0 * crowding - 5.0 * progress;
        // Never open a new bin if some open bin fits the item nearly perfectly.
        if fitting_bins_count > 0 && fit_ratio > 0.7 {
            score += 40.0;
