        score += (post_residual as f64) * 0.06;
    }

    // New-bin deferral — late in the stream, opening a new bin should be
    // strongly discouraged unless the item cannot fit anywhere.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.6 {
        score += 60.0 * progress;
    }

    // REFINED: dead-space ratio — penalize residuals that neither the next item
    // nor any plausible item band can absorb, weighted by how much of the
    // capacity remains stranded.
    if post_residual > 0 {
        let stranded = post_residual as f64 / bin_capacity as f64;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        let reusable_band = post_residual <= 12 || post_residual % 5 == 0;
        if !usable_by_next && !reusable_band {
            score += stranded * 45.0 * (0.6 + progress);
        }
    }

    // REFINED: fit-margin sharpening — when the item nearly exactly fills the
    // bin residual (slack <= 5), reward progressively harder.
    if post_residual > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        if slack <= 5 {
            score -= (6.0 - slack as f64) * 6.0;
        }
    }

    // REFINED: next-item stranding guard — if placing the item here leaves a
    // residual that the next item cannot fit but another open bin's residual
    // could, mildly prefer the alternative (avoid creating dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // NEW: stranded-fraction escalation — dead space in the mid band (13-30)
    // that no known item can use is the main residual-variance driver; scale
    // the penalty with the fraction of the item's own size that is wasted.
    if post_residual > 12 && post_residual < 30 && next_item_size > post_residual {
        let waste_frac = post_residual as f64 / (item_size.max(1) as f64);
        score += waste_frac * 9.0 * (0.4 + progress);
    }

    // NEW: two-item closure check — if the next item plus a plausible small
    // third item (<= 10) exactly closes the bin, reward the chain strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 10 {
            score -= 20.0 * (1.0 - progress * 0.5);
        }
    }

    // NEW: bin-capacity-relative near-closure — when the post residual is
    // within 6 of zero relative to a typical item, treat it as nearly closed
    // and reward proportionally to remaining open-bin pressure.
    if post_residual > 0 && post_residual <= 6 {
        score -= 10.0 + open_bins_count as f64 * 0.8;
    }

    // NEW: new-bin guard refinement — opening a bin for a small item when
    // large residual space exists elsewhere is wasteful; penalize harder as
    // the item shrinks relative to capacity.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size <= 30 {
        score += (30 - item_size) as f64 * 1.5;
    }

    // NEW (gen 13): residual-continuity lookahead — if the post residual can
    // host the next item AND the leftover r2 is at least half the next item
    // (so a following small item likely fits), this bin is a strong chain
    // anchor; reward scaled by how tight the chain is.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if next_item_size > 0 && r2 * 2 >= next_item_size && r2 <= next_item_size {
            score -= 9.0 * (1.0 - progress * 0.4);
        }
    }

