    // (post_residual == 0 handled above), also reward near-zero slack relative
    // to the bin's own residual, sharpening best-fit under many alternatives.
    if bin_residual >= item_size && bin_residual - item_size <= 2 && bin_residual < bin_capacity {
        score -= 26.0;
    }

    // NEW (gen 13): mean-residual-aware stranding — a post residual far below
    // the mean residual is unlikely to be revisited; penalize if it cannot
    // host the next item, reward if it can (targets residual variance).
    if post_residual > 0 && next_item_size > 0 {
        let below_mean = (bin_residual as f64) < mean_residual;
        if below_mean && post_residual < next_item_size {
            score += 10.0;
        } else if below_mean && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // NEW (gen 13): late-stream exact-closure pressure — near the end, prefer
    // the placement that leaves the smallest residual, weighted heavily.
    if progress > 0.75 {
        score += (post_residual as f64) * 0.5 * (progress - 0.75) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
