    // Triple-fill lookahead — reward when item + next item leaves a residual
    // that matches a plausible small item (quarter-capacity band).
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 25 && r2 >= item_size / 4 {
            score -= 12.0;
        }
