    // residual that the next item cannot fit but another open bin's residual
    // could, mildly prefer the alternative (avoid creating dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // NEW: dual-fit chain — reward when both the current item and the next item
    // fit the residual with the *second* placement leaving a near-zero slack,
    // i.e. the bin closes in exactly two more steps.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
