pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes of 10 (capacity fraction bands)
    let class = post_residual / 10; // 0..10 integer division threshold
    // Dead space penalty grows superlinearly for small unusable residues
    if post_residual > 0 {
        score += 60.0 / (post_residual as f64);
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Modulo arithmetic on capacity fractions: bins whose residual falls on
    // "harmonic" boundaries (multiples of 25) are more reusable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 30.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack as f64).min(40.0);
            // penalize if next item leaves another awkward residue
            if slack > 0 && slack <= 5 {
                score -= 20.0;
            }
        } else {
            // post residual too small for next item: penalize proportionally
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current
    // post residual would be tiny (i.e., we're placing into an empty bin and
    // the item is huge). Empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, mitigated when item is large
        score += 40.0 - (item_size as f64) * 0.35;
        // opening a new bin is better if all existing residuals are too small
        // for the item anyway (then fitting_bins_count would be 0 among open,
        // but new bin also counts) — favor new bin when mean residual is low
        score -= (100.0 - mean_residual) * 0.1;
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress;

    // Slight preference to balance bins when many are open
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

