    // leftover residual proportionally, forcing tighter fills mid/late stream.
    if post_residual > 0 {
        score += (post_residual as f64) * 0.08 * progress;
    }

    // Exact post-residual reusability — reward when the post residual can
    // exactly host any small future item (residual in common small-item band).
    if post_residual > 0 && post_residual <= 12 && progress > 0.35 {
        score -= 18.0;
    }

    // Dead-space ratio penalty scaled by how few bins can still use this
    // residual band — residuals near item sizes are reusable, others are waste.
    if post_residual > 0 && next_item_size > 0 {
        let reusability = if post_residual >= next_item_size { 0.0 }
            else if post_residual >= next_item_size / 2 { 8.0 }
