    }

    // Open-bin consolidation — when many bins are open, prefer the bin
    // whose post residual is closest to zero (hardest bin to close first).
    if open_bins_count > 4 && bin_residual < bin_capacity && post_residual > 0 {
        score += (post_residual as f64) * 0.06;
    }

