    }

    // NEW: stranded-fraction escalation — penalize residuals in the classic
    // dead band (just above half capacity) that no typical item can consume,
    // weighted by how many other bins could still host the item instead.
    if post_residual > 50 && post_residual < bin_capacity
        && next_item_size > 0 && next_item_size < post_residual - 25 {
        score += (post_residual as f64 - 50.0) * 0.4
            * (1.0 + (fitting_bins_count as f64).min(4.0) * 0.15);
    }

    // NEW: near-exact next-fit — the residual left after placement is within a
    // tiny margin of the next item, guaranteeing near-zero future waste.
    if next_item_size > 0 && post_residual > next_item_size {
        let d = post_residual - next_item_size;
