    // they nearly exhaust; otherwise the residual becomes permanent waste.
    if item_size >= 60 && post_residual > 0 && post_residual <= 15 {
        score -= 26.0;
    }

    // NEW: small-item conservation — tiny items early in the stream should not
    // burn large residuals that big items could otherwise use.
    if item_size <= 8 && post_residual > 60 && progress < 0.4 {
        score += 10.0 * (1.0 - progress * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

