    } else if fill_ratio > 0.6 {
        score -= 12.0 * fill_ratio;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - fill_ratio) * 2.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

