    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: post_residual exactly matches the next item's size.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if diff == 0.0 {
            score -= 800.0; // chain fit: next item fills this bin perfectly
        } else if diff <= 5.0 {
            score -= 200.0 - diff * 20.0; // near-chain fit
        } else {
            // penalize residuals too small for the next item (dead space)
            if pr < nx {
                score += (nx - pr) * 1.5;
