    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - pr) * 0.8;
    }

    // Last-chance bin: only bin that fits; reward using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize creating tiny unusable slivers (<=10 unusable for typical items).
    if pr > 0.0 && pr <= 10.0 {
        score += 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless no decent fit exists.
    if bin_residual == bin_capacity {
        score += 400.0;
        // If this is a last-chance situation, opening a new bin is less bad.
        if fitting_bins_count == 0 {
            score -= 350.0;
