    // whose post residual is closest to zero (hardest bin to close first).
    if open_bins_count > 4 && bin_residual < bin_capacity && post_residual > 0 {
        score += (post_residual as f64) * 0.06;
    }

    // New-bin deferral — late in the stream, opening a new bin should be
    // strongly discouraged unless the item cannot fit anywhere.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.6 {
        score += 60.0 * progress;
    }

    // REFINED: dead-space ratio — penalize residuals that neither the next item
    // nor any plausible item band can absorb, weighted by how much of the
    // capacity remains stranded. Targets the diagnosed dead-space weakness.
    if post_residual > 0 {
        let stranded = post_residual as f64 / bin_capacity as f64;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        let reusable_band = post_residual <= 12 || post_residual % 5 == 0;
        if !usable_by_next && !reusable_band {
            score += stranded * 45.0 * (0.6 + progress);
        }
    }

    // REFINED: fit-margin sharpening — when the item nearly exactly fills the
    // bin residual (slack <= 5), reward progressively harder.
    if post_residual > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        if slack <= 5 {
            score -= (6.0 - slack as f64) * 6.0;
        }
    }

