    // residual that the next item cannot fit but another open bin's residual
    // could, mildly prefer the alternative (avoid creating dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // NEW: stranding-risk coupling — if the next item fits here exactly but
    // would leave this bin closed, prefer that over leaving a mid-band residual
    // that no plausible future item can absorb (dead-space prevention).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.9 * (0.4 + progress);
    }

    // NEW: exact-fit chain anticipation — when the item exactly fills the bin
    // residual is already rewarded via post_residual == 0; additionally reward
    // placements where the next item exactly closes what remains.
    if next_item_size > 0 && post_residual > 0 && post_residual == next_item_size {
        score -= 30.0 * (0.5 + progress);
    }

    // NEW: dual-fit lookahead — reward when item + next item leave a residual
    // that the next item itself could pair into (r2 == next_item_size), which
    // closes the bin on the third placement.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 26.0;
        }
    }

    // NEW: residual-band discrimination — residuals in the 13-19 band are
    // rarely usable by mid-size items; penalize creating them, but only when
    // the next item cannot consume them (avoids double-penalizing good fits).
    if post_residual >= 13 && post_residual <= 19
        && next_item_size > post_residual && fitting_bins_count > 1 {
        score += 10.0 + 4.0 * progress;
    }

    // NEW: compaction pressure scaled by stream position — the longer the
    // stream, the more each wasted unit of residual costs in expectation.
    let stream_scale = 1.0 + (total_items as f64).ln().max(1.0) * 0.05;
    if post_residual > 0 {
        score += (post_residual as f64) * 0.04 * stream_scale * (0.3 + progress);
    }

    // NEW: open-bin economy — when few bins are open, prefer keeping residuals
    // large and reusable; when many are open, prefer closing bins fast.
    if open_bins_count <= 3 && post_residual > 40 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // GEN-15 MUTATION: dead-space gradient refinement — replace the flat
    // stranded penalty with a convex quadratic in the stranded fraction so
    // large dead spaces are punished disproportionately, and add a
    // "salvageability" check: a residual is salvageable if ANY of the common
    // item-size bands (small items 1-12, mid 20-35, half-capacity) could
    // still consume it; only truly stranded residuals get the convex hit.
    if post_residual > 0 {
        let stranded = post_residual as f64 / bin_capacity as f64;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        let salvageable = post_residual <= 12
            || post_residual % 5 == 0
            || (post_residual >= 20 && post_residual <= 35 && item_size <= post_residual);
        if !usable_by_next && !salvageable {
            score += stranded * stranded * 130.0 * (0.5 + progress);
        }
    }

    // GEN-15 MUTATION: mean-residual attraction — prefer bins whose post
    // residual sits close to the mean residual of the pool; homogenizing
    // residuals raises the chance a future item fits many bins at once,
    // directly reducing residual variance (sigma_res diagnosis).
    if post_residual > 0 && mean_residual > 0.0 {
        let dev = ((post_residual as f64) - mean_residual).abs();
        score -= (30.0 / (1.0 + dev * 0.15)) * (1.0 - progress) * 0.35;
    }

    // GEN-15 MUTATION: tight-slack lookahead sharpening — when the next item
    // fits with slack 1-6, escalate the reward quadratically; near-exact
    // two-step chains are the dominant source of closed bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 6 {
            score -= (7.0 - slack as f64) * (7.0 - slack as f64) * 1.4;
        }
    }

    // GEN-15 MUTATION: adaptive new-bin barrier — scale the new-bin penalty
    // with both fitting-bin quality and stream progress; if the best existing
    // fit leaves more than 25% waste, allow a new bin earlier (mid-stream)
    // to avoid trapping the item in a bad fit that strands future items.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let bad_fit_threshold = 25.0;
        let best_existing_waste = if next_item_size > 0 {
            // proxy: item leaves large residual relative to capacity
            (post_residual as f64 / bin_capacity as f64) * 100.0
        } else {
            0.0
        };
        if progress > 0.75 {
            score += 90.0 * progress;
        } else if best_existing_waste > bad_fit_threshold && progress < 0.4 {
            score -= 12.0; // early stream: fresh bins acceptable for bad fits
        } else {
            score += 20.0;
        }
    }

    // GEN-15 MUTATION: half-residual trap — creating a residual exactly equal
    // to half the next item (or half of a plausible item) is a strong
    // closing signal; reward it, since one more same-size item closes the bin.
    if post_residual > 0 && next_item_size > 0 && post_residual * 2 == next_item_size {
        score -= 20.0 * (0.5 + progress);
    }

    // GEN-15 MUTATION: late-stream exact-closure escalation — near the end,
    // any placement leaving residual <= next_item_size/2 is nearly closed;
    // reward aggressively to squeeze out the last bins.
    if progress > 0.8 && post_residual > 0 && next_item_size > 0
        && post_residual <= next_item_size / 2 {
        score -= 26.0 * progress;
    }

    score
}

