    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.9;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: attractive only when no alternative exists; late-stream deferral.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -35.0
        } else if progress > 0.6 {
            100.0 + open_bins_count as f64 * 2.2 + 60.0 * progress
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -25.0
        } else {
