    if fitting_bins_count > 1 && post_residual > 0 {
        score += (post_residual as f64) * 0.12;
    }

    // NEW: perfect-closure anticipation — if next item exactly equals the
    // pre-residual minus current item, the chain closes the bin exactly.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 52.0;
    }

    // NEW: small-residual recycling bonus — residuals in the most common
    // item band (1-25) stay usable; reward keeping them around mid-stream.
    if post_residual >= 1 && post_residual <= 25 && progress >= 0.2 && progress <= 0.8 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic in fill ratio of the residual used.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize small dead space that nothing (min size 1) can still use poorly:
    // tiny residuals (1..=3) are near-useless; big residuals are flexible.
    if post_residual > 0 && post_residual <= 5 {
        score += 12.0;
    }

    // Lookahead: reward if next item exactly matches the post-residual (k=2 chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead compatibility: closer match is better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (-gap / 20.0).exp();
        } else {
            // Next item cannot use this residual: mild penalty proportional to wasted potential.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, keep bins flexible (penalize low post_residual);
    // late in the stream, aggressively fill bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost plus penalty when open bins are plentiful
        // and their average residual is large (i.e., existing bins are underused).
        let mut new_bin_score = 55.0;
        new_bin_score += 3.0 * open_bins_count as f64;
        new_bin_score += 0.4 * mean_residual;
        // Late in the stream, opening bins is cheaper (no long-term fragmentation risk).
        new_bin_score -= 20.0 * progress;
        // If next item is huge and would not fit any typical residual, new bin is fine.
        if next_item_size > 60 {
            new_bin_score -= 10.0;
        }
        return new_bin_score;
    }

    // Prefer bins whose residual deviates below the mean (they are the "tightest" candidates).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

