    // Late-stream exact-closure pressure — smallest post residual dominates.
    if progress > 0.75 {
        score += (post_residual as f64) * 0.5 * (progress - 0.75) * 4.0;
    }

    // Residual-continuity lookahead — post residual hosts next item AND the
    // leftover r2 sits between half and full next item size.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 >= next_item_size && r2 <= next_item_size {
            score -= 9.0 * (1.0 - progress * 0.4);
        }
    }

    // Exact-fit dominance — item nearly fills the bin residual exactly.
    if bin_residual >= item_size && bin_residual - item_size <= 2 && bin_residual < bin_capacity {
        score -= 26.0;
    }

    // New-bin guard for small items — opening a bin for a small item when
    // large residual space exists elsewhere is wasteful.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size <= 30 {
        score += (30 - item_size) as f64 * 1.5;
    }

    // Near-closure bonus scaled by open-bin pressure.
    if post_residual > 0 && post_residual <= 6 {
        score -= 10.0 + open_bins_count as f64 * 0.8;
    }

    // Two-item closure check — next item plus a small third item closes the bin.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 10 {
            score -= 20.0 * (1.0 - progress * 0.5);
        }
    }

    // Mid-band dead-space escalation — 13-30 residual unusable by next item.
    if post_residual > 12 && post_residual < 30 && next_item_size > post_residual {
        let waste_frac = post_residual as f64 / (item_size.max(1) as f64);
        score += waste_frac * 9.0 * (0.4 + progress);
    }

    // GEN 18: fine-grained residual compaction — reward placements whose post
    // residual is a small multiple of the next item size (exact chain packing).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let r = post_residual % next_item_size;
        if r == 0 && post_residual / next_item_size <= 4 {
            score -= 14.0;
        } else if r <= 2 {
