    // GEN 18: combined compaction coupling — reward near-exact fit AND a
    // post residual that hosts the next item (fine-grained fit + lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let consumed = bin_residual.saturating_sub(item_size) as f64;
        let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
        if fit_quality > 0.85 && consumed <= 100 {
            score -= 11.0 * (0.5 + progress);
        }
    }

    // GEN 18: dead-space minimization — penalize post residuals that neither
    // the next item nor typical small items can consume, scaled by progress.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let dead_frac = post_residual as f64 / (next_item_size as f64);
        score += dead_frac * 18.0 * (0.5 + progress);
    }

    // GEN 18: new-bin acceptance tuned to item size — large items may open
    // bins mid-stream; small items must reuse existing space.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if item_size >= 60 {
            score -= 10.0 * (1.0 - progress);
        } else {
            score += (60 - item_size) as f64 * 0.6 * (0.5 + progress);
        }
    }

    // GEN 19 MUTATION: lookahead-fit synergy — when the item nearly exhausts the
    // residual AND the leftover exactly hosts the next item, this is a
    // two-item closure; reward proportionally to fit quality.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual as f64;
        score -= fq * 40.0;
    }

    // GEN 19 MUTATION: fragmentation trap — post residual just below next item
    // (off-by-small gap) is the worst kind of dead space; penalize harder when
    // few alternatives exist to absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8 {
            score += (8.0 - gap) * 3.5 * (1.0 + progress);
        }
    }

    // GEN 19 MUTATION: scarce-alternative tightening — when only one or two
    // bins can host the next item, protect bins that keep that possibility.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }

    // GEN 19 MUTATION: dual residual divisibility — post residual divisible by
    // both 3 and next item size suggests a clean multi-item closure chain.
    if next_item_size > 2 && post_residual > 0 && post_residual % next_item_size == 0
        && post_residual % 3 == 0 {
        score -= 6.0;
    }

    // GEN 19 MUTATION: late-stream small-residual closure race — when near the
    // end, prefer bins whose post residual is the globally smallest achievable.
    if progress > 0.8 && post_residual > 0 && post_residual <= 5 {
        score -= 15.0 * (progress - 0.8) * 5.0;
    }

    // GEN 20 MUTATION: combined fine-grained compaction + lookahead — reward
    // placements where the post residual can host the next item AND the fit
    // quality is very high (best-fit chain), scaled by fitting scarcity.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        if fq > 0.9 {
            score -= (fq - 0.9) * 90.0 * (1.0 - progress * 0.3);
        }
        if fitting_bins_count > 3 {
            score -= 6.0;
        }
    }

    // GEN 20 MUTATION: dead-space ratio sharpening — post residual that is a
    // small fraction of the next item is nearly-certain waste; penalize
    // proportionally to the unusable fraction and open-bin pressure.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.5 {
            score += (0.5 - unusable) * 30.0 * (0.6 + progress)
                + open_bins_count as f64 * 0.4;
        }
    }

    // GEN 20 MUTATION: new-bin acceptance with lookahead trade-off — opening a
    // fresh bin is acceptable only when the item is large and the next item
    // would strand no existing residual; otherwise penalize with a
    // progress-scaled barrier.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 22.0 + 30.0 * progress;
        }
    }

    // GEN 20 MUTATION: residual-chain harmony — post residual equal to the
    // sum of the next item and a plausible third small item (<= 20) closes
    // the bin in two more steps; reward scaled by progress.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 9.0 * (0.6 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Non-linear coupling of post residual with stream progress:
    // late in the stream, tighter packing (small post_residual) matters more.
    let tightness = 1.0 - norm_pr;
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Quadratic penalty on large wasted residual, scaled by progress.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits smoothly (cubic term).
    score -= 8.0 * fit_ratio * fit_ratio * fit_ratio;

    // Last-chance bin bonus (smooth, not piecewise).
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 10.0 * last_chance * last_chance;

    // Lookahead: prefer leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mean-residual coupling: penalize bins far from the fleet mean (smooth).
    score += 2.0 * ((pr as f64 - mean_residual) / cap).abs();

    // Mild new-bin aversion grows with progress.
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * progress;
    }

    score
}

