pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Class 0: post_residual divisible by large chunk sizes -> highly reusable.
    let post = post_residual as u32;
    let class = if post == 0 {
        0.0
    } else if post <= 10 {
        1.0 // tiny sliver, nearly dead space
    } else if post % 10 == 0 {
        0.5 // aligns with decade granularity
    } else if post >= 30 {
        2.0 // roomy, can host medium items
    } else {
        3.0 // awkward mid-range leftover
    };
    score += class * 4.0;

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin unless it enables a great pairing.
        score += 30.0;
        // If the next item could exactly pair with this item in a fresh bin,
        // opening a new bin is great (classic 2-item exact-fill logic).
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_left = bin_capacity - item_size - next_item_size;
            if pair_left <= 10 {
                score -= 60.0;
            } else if item_size + next_item_size >= bin_capacity * 8 / 10 {
                score -= 25.0;
            }
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Prefer filling bins whose residual is far below the mean (reduce spread).
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
        // Lookahead: if next item exactly fills the post residual, big reward.
        if next_item_size == post && post > 0 {
            score -= 40.0;
        } else if next_item_size > 0 && next_item_size <= post {
            // next item fits: mildly reward leaving a usable gap
            score -= (post - next_item_size) as f64 * 0.2;
        }
    }

    // Penalize creating dead space below the smallest plausible item (<=10).
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 && !is_new_bin {
        score -= 2.0;
    }

    score
}

