    // pure waste; escalate the push to close bins completely.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // MUTATION: two-item closure sweep — if the next item exactly fills the
    // post residual OR the post residual halves into a plausible future fill,
    // reward more aggressively mid-stream where compaction pays off most.
