    // the next item closes this bin and few alternatives exist, this is the
    // highest-value compaction event; escalate the reward.
    if next_item_size > 0 && post_residual == 0 {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.5 };
        score -= 90.0 * scarcity * (0.5 + progress);
    }

