    // residual that neither the next item nor a half-split can consume,
    // scaled by how much of the bin's remaining space is stranded.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded_frac = post_residual as f64 / bin_residual.max(1) as f64;
