    }

    // NEW: new-bin opportunity-cost refinement — a fresh bin is only worth
    // opening when the current item is large relative to all open residuals;
    // otherwise keep compacting existing space.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let min_alt_residual: f64 = mean_residual;
        if item_size as f64 > min_alt_residual * 0.85 && next_item_size >= item_size {
            score -= 30.0;
        }
    }

    score
}

