            score -= (11.0 - slack as f64) * 3.5 * (1.0 - progress * 0.5);
        }
    }

    // NEW: new-bin gate refinement — mid-stream, only open a fresh bin when the
    // item is large relative to capacity and no open bin leaves a decent slack.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress >= 0.3 && progress <= 0.6 {
        if item_size < 45 {
            score += 22.0;
        }
    }

    score
}

