    // of the bin, complementing the >0.7 threshold bonus with a continuous
    // term so that near-ties consistently favor the tighter placement.
    if bin_residual < bin_capacity {
        let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_frac * 9.0 * (0.3 + progress);
    }

