    // within a tight window around the fleet mean, since such residuals are
    // most likely to be combinable with future items across all bins.
    if post_residual > 0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        if diff <= 6.0 {
            score -= (6.0 - diff) * 1.6;
        }
    }

