    // post residual can host it, penalize proportionally to how much slack
    // is stranded relative to the next item, weighted by open-bin count.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && next_item_size >= 40 {
        score += (next_item_size - post_residual) as f64 * 0.35 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
