        }
    }

    // GEN 23 MUTATION: late-stream exact-closure pressure — smallest post
    // residual dominates near the end of the stream.
    if progress > 0.75 {
        score += (post_residual as f64) * 0.5 * (progress - 0.75) * 4.0;
    }

    score
}

