        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling for large next items.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-combinability index — reward post residuals expressible
    // as sums of two common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
        if combinable {
            score -= 7.0 * (0.5 + progress);
        }
    }

    // Slack-variance squeeze — when several bins fit, sharpen preference
    // toward the bin whose post residual best matches the mean residual.
    if fitting_bins_count > 2 && post_residual > 0 && bin_residual < bin_capacity {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.10 * progress;
    }

    // Triple-fill exact anticipation — current + next leaves a residual
    // equal to a plausible third item (half of next), enabling full closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // New-bin gating refinement — block fresh bins when a near-exact fit exists.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size >= 90 {
        score += 40.0;
    }

    // BORROWED: residual-decay gradient — reward consuming >70% of the residual.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // BORROWED: stranded-gap arithmetic guard — 31-59 band unreachable dead space.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // BORROWED: two-item sum closure — r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // BORROWED: new-bin parity refinement — prefer fresh bins early, not late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW MUTATION: exact-division chain — if the residual divides evenly by
    // a plausible future item size (residual/k for k=2..4), reward the bin:
    // repeated identical items can close it with zero waste.
    if post_residual > 0 && post_residual < bin_capacity {
        let mut div_bonus = 0.0;
        for k in 2..=4u32 {
            if post_residual % k == 0 {
                let part = post_residual / k;
                if part >= 1 && (part == next_item_size || part >= next_item_size / 2) {
                    div_bonus += 9.0;
                }
            }
        }
        score -= div_bonus * (0.4 + progress);
    }

    // NEW MUTATION: waste-floor coupling — when the item nearly empties the bin
    // but leaves 1-2 units, treat it as closed (tiny residuals are pure waste
    // no future item of size>=3 can use); reward harder late in the stream.
    if post_residual >= 1 && post_residual <= 2 && item_size >= 3 {
        score -= 70.0 * (0.5 + progress);
    }

    // NEW MUTATION: scarcity-driven new-bin suppression — when only one bin
    // fits and the item leaves a small usable residual, strongly prefer it
    // over opening a fresh bin (avoids bin-count inflation).
    if bin_residual == bin_capacity && fitting_bins_count == 1 {
        let post_ok = post_residual <= 15 || post_residual >= next_item_size;
        if post_ok {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
