    // this bin can host both, reward keeping the post residual exactly able
    // to chain; otherwise steer the big item toward the emptiest usable bin.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum of current and next against
    // the full bin — rewards placements that set up a two-item exact closure.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — reward consuming >70% of the residual with
    // an escalating bonus as the fraction approaches 1; sharpened mid-stream.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 62.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size
    // are prime dead space; penalize proportionally to how unreachable.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: dead-space density floor — the primary diagnosed weakness is
    // leftover dead space. Penalize any nonzero post residual by a graded
    // convex function that bites hardest on small residuals (which are the
    // hardest to combine) yet still scales with absolute size, so mid-band
    // gaps are never free. This replaces flat waste terms with a smooth
    // gradient that continuously steers toward exact closure.
    if post_residual > 0 && post_residual < bin_capacity {
        let r = post_residual as f64;
        let density = r / bin_capacity as f64;
        score += density * r * 0.09 * (0.55 + progress);
        // Tiny residuals are nearly closed bins: extra reward pressure.
        if r <= 6.0 {
            score -= (7.0 - r) * 5.5;
        }
    }

    // NEW: combinatorial headroom guard — prefer placements whose post
    // residual remains expressible as a sum of two plausible item sizes
    // (both <= 50), since most items are small-to-mid; residuals outside
    // that two-sum reach are likely to strand permanently.
    if post_residual > 0 && post_residual < bin_capacity {
        let r = post_residual;
        let two_sum_reachable = r <= 100; // any residual <= 100 can be split as a+b with a,b <= 50 when r <= 100
        if !two_sum_reachable {
            score += 10.0 + (r as f64 - 100.0) * 0.12;
        } else if r >= 51 && next_item_size > 0 && next_item_size <= 50 {
            // residual 51-100 with small next item: check if remainder stays combinable
            let rem = r - next_item_size;
            if rem > 50 {
                score += 6.0;
            }
        }
    }

    // NEW: fitting-count-aware best-fit escalation — with many candidate
    // bins, intensify the preference for the bin whose post residual is
    // smallest, sharpening best-fit exactly when choice is richest.
    if fitting_bins_count >= 2 && bin_residual < bin_capacity && post_residual > 0 {
        score += (post_residual as f64) * 0.045 * ((fitting_bins_count.min(8)) as f64 / 8.0);
    }

    // NEW: next-item dual-hosting bonus — when the next item is large
    // (>= 40), reward placements that leave the post residual able to host
    // it while keeping some slack, avoiding a forced fresh bin next step.
    if next_item_size >= 40 && post_residual >= next_item_size && bin_residual < bin_capacity {
        let slack = post_residual - next_item_size;
        if slack <= 15 {
            score -= 12.0;
        }
    }

    score
}

