        let pressure = if open_bins_count > 5 { 0.10 } else if open_bins_count > 2 { 0.05 } else { 0.0 };
        score += (post_residual as f64) * pressure * (0.5 + progress);
    }

    // NEW: next-item large guard — when the upcoming item is large (>45),
    // heavily reward the placement that leaves exactly enough room for it,
    // and penalize placements that strand it with no home.
    if next_item_size > 45 {
        if post_residual == next_item_size {
            score -= 40.0 * (0.5 + progress);
        } else if post_residual > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
            score += 18.0 * (0.5 + progress);
        }
    }

    score
}

