    // that small items would fill inefficiently; push them to near-exact fits.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — when options are few, reward the
    // bin that stays most reusable for the unknown remainder of the stream.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — in the final stretch, any nonzero residual is nearly
    // pure waste; escalate the push to close bins completely.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze — tighten the residual-variance budget
    // by rewarding placements that leave post residual close to a small
    // modular residue class (highly combinable), penalizing odd stragglers.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — when the next item is large and only
    // this bin can host both, reward keeping the post residual exactly able
    // to chain; otherwise steer the big item toward the emptiest usable bin.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum of current and next against
    // the full bin — rewards placements that set up a two-item exact closure.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — reward consuming >70% of the residual,
    // with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size
    // are prime dead space; penalize proportionally to how unreachable.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: dead-space budget coupling — the fleet's total residual capacity
    // per open bin estimates average stranded space; placements that leave
    // a post residual far below that average are the best compaction moves.
    if post_residual > 0 && open_bins_count > 0 && bin_residual < bin_capacity {
        let avg_dead = mean_residual / open_bins_count as f64;
        if (post_residual as f64) < avg_dead {
            score -= (avg_dead - post_residual as f64).min(25.0) * 0.5 * (0.5 + progress);
        } else {
            score += ((post_residual as f64) - avg_dead).min(30.0) * 0.22;
        }
    }

    // NEW: exact-closure shadowing — when this bin's residual equals the item
    // plus a tiny sliver (1-3), the leftover is nearly unusable; push the item
    // toward bins where the sliver disappears entirely instead.
    if post_residual >= 1 && post_residual <= 3 && next_item_size > post_residual {
        score += 18.0 * (0.6 + progress);
    }

    // NEW: mean-residual cross harmony — a post residual matching the current
    // mean residual is statistically the most likely to be filled by future
    // items drawn from the same distribution; reward this alignment.
    if post_residual > 0 && (post_residual as f64 - mean_residual).abs() <= 2.0 {
        score -= 9.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 25.0;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how much of post_residual the next item consumes.
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * fill;
        } else {
            // Next item won't fit: penalize leaving large awkward gaps.
            score += (post_residual as f64 - (post_residual as f64 % next_item_size as f64)) * 0.05;
        }
    } else {
        // Last item: prefer filling an existing bin as fully as possible.
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or very fragmented.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        // Opening a new bin is good if existing residuals are small (bins nearly full)
        // or there are many bins already (diversity of residual sizes).
        if avg_tightness < 0.25 {
            score -= 30.0 * (0.25 - avg_tightness) / 0.25;
        } else {
            score += 20.0 + avg_tightness * 40.0;
        }
        // Early in the stream, opening bins is cheaper (long horizon to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // Slight penalty for proliferating bins late.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0 * progress;
    }

    // Penalize placing into bins whose residual is much larger than needed (wasteful).
    if bin_residual > item_size {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += waste_ratio * 15.0;
    }

    // Mild preference for bins with residual close to mean (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

