        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: wasted-fraction escalation — dead space measured as a fraction of
    // the remaining residual is the true enemy; penalize placements that
    // strand more than a quarter of the residual when nothing can follow.
    if post_residual > 0 && bin_residual < bin_capacity {
        let stranded_frac = post_residual as f64 / bin_residual as f64;
