    if post_residual > 0 && post_residual * 2 == bin_residual {
        score -= 10.0 + open_bins_count.min(8) as f64 * 2.0;
    }

    // NEW: next-item exact closure with scarcity weighting — when the next
    // item exactly consumes the post residual, prefer this bin more strongly
    // the fewer fitting alternatives exist (avoid losing the perfect pair).
    if next_item_size > 0 && post_residual > 0 && post_residual == next_item_size {
        let scarcity = (fitting_bins_count.max(1) as f64).recip();
        score -= 18.0 + 30.0 * scarcity;
    }

    // NEW: mid-band residual floor — residuals in the 14-29 band are the
    // hardest to combine; penalize leaving them unless the next item fits.
    if post_residual >= 14 && post_residual <= 29 && !(next_item_size > 0 && post_residual >= next_item_size) {
        score += 9.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + 0.8 * t - 1.2 * t * t + 0.6 * t * t * t;
    score *= poly;

    // Tight fits rewarded: quadratic decay of residual.
    score -= 0.5 * (cap - pr) * (cap - pr) / cap;

    // Penalize dead space relative to mean residual, scaled by progress.
    score += (pr - mean_residual).abs() * (0.3 + 0.7 * t);

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + t);
    }

    // Lookahead: prefer leaving space compatible with next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 0.4 * n * (1.0 - norm_pr);
        } else {
            score += 0.3 * (n - pr);
        }
    }

    // Mild pressure to reuse existing bins as stream progresses.
    score += (open_bins_count as f64) * 0.05 * t;

    // New-bin candidate: make it costly unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * t;
    }

    score
}

