        }
    }

    // NEW: residual variance squeeze — prefer post residuals close to the
    // fleet mean when many bins remain open, improving future combinability.
    if open_bins_count > 5 && post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.05 * (0.4 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: residues that are "usable" ---
    // Class bins by post_residual modulo coarse capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Harmonic residue classes: post_residual % (cap/4) and % (cap/8)
    let r4 = post_residual % quarter.max(1);
    let r8 = post_residual % eighth.max(1);

    // Small residues mean the leftover aligns with common item sizes -> reward.
    let small_r4 = (r4 as f64).min((quarter - r4) as f64);
    let small_r8 = (r8 as f64).min((eighth - r8) as f64);
    score -= 0.9 * small_r4 + 0.5 * small_r8;

    // Integer-division threshold on post_residual: how many "medium" chunks fit.
    let chunks = post_residual / 20; // cap/5 chunks
    score -= 3.0 * (chunks.min(4) as f64);

    // Dead-space penalty: post residual too small for any plausible item (1..100 stream)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // harmonic match of next item to residual class
            let nmod = next_item_size % 20;
            if nmod == post_residual % 20 {
                score -= 4.0;
            }
        } else {
            score += 4.0; // next item won't reuse this bin
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        // Prefer new bin only when existing bins are very fragmented or few fit.
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        let new_bin_score = cap * (1.0 - 0.35 * fragmentation) - 8.0 * (fitting_bins_count.min(3) as f64);
        score = score.max(new_bin_score) + 18.0 * (1.0 - progress);
        if fitting_bins_count > 0 && post_residual as f64 >= 0.25 * cap {
            score += 30.0; // a decent fit exists, discourage new bin
        }
    }

    // Mild pressure to prefer fuller bins as stream progresses.
    score -= 0.02 * (item_size as f64);
    score += 0.05 * (open_bins_count as f64) * (post / cap);

    score
}

