            score -= consumed * 22.0 * (0.4 + progress);
        }
    }

    // MUTATION: endgame new-bin hard block — never open bins near the end
    // when any existing bin can host the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.85 {
        score += 90.0;
    }

