}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal leftover, but dead space in the "unusable" band
    // (small gaps that few future items can fill) is penalized super-linearly.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are nearly useless
    // (min item size is 1, but small gaps rarely match); penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Tightness ratio: reward placements that consume a large fraction
    // of the bin's current residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_frac;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // penalize the new-bin candidate (bin_residual == bin_capacity) more
    // as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.5 * open_bins_count as f64;
    } else {
        // Slight reward for reusing existing bins, scaled by pressure.
        score -= (open_bins_count as f64).min(10.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward leaving that gap; if next item cannot fit anyway, the gap
    // is dead space — penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0; // chains nicely
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 3.0; // gap too small for lookahead
        }
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a good residual portfolio; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        score += 3.0 * progress;
    }

    // Prefer bins whose residual is close to the current mean residual
    // (keeps the portfolio homogeneous and predictable).
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    score
}

