    // post-placement residual (capacity - item) is large enough to remain
    // fully combinable, or when no alternative exists; otherwise nudge the
    // item toward the best partial fit to avoid bin sprawl.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_left = bin_capacity.saturating_sub(item_size);
        if fresh_left < 30 && next_item_size > fresh_left {
            score += 26.0;
        }
    }

    score
}

