pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item nearly fills the bin.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - residual_frac).powi(6);

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain placement
        } else if next_item_size <= post_residual {
            // partial chain fit: reward proportional to how much of post_residual is used
            let chain_frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_frac.powi(2);
        } else {
            // next item cannot fit here: penalize leaving large dead space
            let waste_frac = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 15.0 * waste_frac;
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins.
    // Favor bins whose post_residual lands near mean_residual (keeps bins uniform)
    // but strongly penalize post_residual far below the smallest useful item.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Penalize small unusable residuals (dead space below typical minimum item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when the item is small relative to capacity
    // and existing bins would leave very tight fits.
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: item_size leftover; adjust by stream position.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress);
        // If many bins are open, discourage proliferation.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Slight bonus for using existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    score
}

