    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — REINFORCED: reward consuming >65% of the
    // residual with a steeper escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.65 {
            score -= (consumed - 0.65) * 75.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: waste-floor targeting — the parent leaves ~71 excess bins; drive
    // post residual toward the smallest achievable slack given the next item:
    // reward when post residual is either 0 or exactly next-item-sized (both
    // close/keep bins tight), scaled by how many alternatives exist.
    if next_item_size > 0 && post_residual > 0 {
        let slack_gap = (post_residual as f64 - next_item_size as f64).abs();
        if slack_gap <= 10.0 {
            score -= (10.0 - slack_gap) * 2.2 * (0.5 + progress);
        }
    }

    // NEW: dead-band elimination — residuals that neither the next item nor
    // any plausible small item (1-15) can combine with are pure loss; penalize
    // harder as fitting alternatives grow (scattering is worse then).
    if post_residual > 15 && next_item_size > 0 && post_residual < next_item_size {
        let combinable = post_residual <= 15 || post_residual % 10 == 0;
        if !combinable {
            score += 9.0 + (fitting_bins_count as f64) * 1.5;
        }
    }

    // NEW: next-item-fit precision — when the next item would leave a very
    // small remainder in this bin, prefer this bin decisively (3-step closure).
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 <= 5 {
            score -= (6.0 - r2 as f64) * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 120.0; // near-perfect: residual likely unusable anyway (min item 1..100 unknown, but small waste is cheap)
    }

    // Penalize leaving awkward mid-range dead space that small future items could use.
    if post_residual > 0 && post_residual <= 30 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            // next item cannot fit here; mildly penalize small post residuals that strand capacity
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; relax when many open bins are fragmented.
        score += 90.0;
        // If mean residual is small (open bins are nearly full), opening fresh is more attractive.
        score -= 40.0 * (1.0 - (mean_residual / bin_capacity as f64)).min(1.0);
        // If very few bins can fit this item, opening a new bin is safer.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Late in the stream, avoid spawning bins with tiny expected future utility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Global fragmentation pressure: many open bins with high mean residual -> prefer consolidating
    // into bins with larger residual (this bin's residual above mean is good to use up).
    if open_bins_count > 0 {
        let excess = bin_residual as f64 - mean_residual;
        score -= 10.0 * (excess / bin_capacity as f64);
        score += 3.0 * (open_bins_count as f64).ln() * (1.0 - fill_ratio);
    }

    // Time horizon: early in the stream, be conservative about wasting space; later, prioritize closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress * (1.0 - fill_ratio);

    score
}

