pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, smoothly warped
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear stream progress coupling: later in stream, penalize waste more strongly
    let progress_warp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * progress_warp * norm_pr * norm_pr;

    // Reward tight fits with smooth exponential-like term
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Mean residual coupling: if this bin is near mean residual, mildly favor (balance)
    let dev = (pr - mean_residual) / cap;
    score += 2.5 * dev * dev;

    // Last-chance bonus: only one fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 15.0 + 8.0 * progress_warp;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are poor
    if bin_residual == bin_capacity {
        let mean_pressure = mean_residual / cap;
        let new_bin_penalty = 30.0 - 20.0 * mean_pressure * mean_pressure;
        score += new_bin_penalty + 10.0 * (1.0 - progress);
        // If next item is large, new bin is more attractive
        if next_item_size > 0 {
            score -= 0.15 * next_item_size as f64;
        }
    }

    // Lookahead: penalize leaving post_residual that barely can't fit next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (gap / cap); // next item fits: good
        } else {
            score += 4.0 * (-gap / cap) * (1.0 + progress); // dead space vs next item
        }
    }

    // Crowding: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 0.8 * (1.0 - norm_pr);

    score
}

