    // Mean-residual gap targeting — steer post residual toward fleet mean.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should not leave small mid-band residuals.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — keep bins most reusable when options are few.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Dead-space variance squeeze — modular residue class alignment.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — next item is large: keep chain viable.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against full capacity.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Stranded-gap arithmetic guard — 31-59 band unreachable by next item.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets (capacity fractions of C=100)
    let class = (post_residual % 10) as f64;
    let decade = (post_residual / 10) as f64;

    // Reward tiny post_residual (perfect fits): strongest bonus for class 0
    score -= (10 - class) * 0.8;

    // Penalize dead-space decades: residual in 30..70 is least reusable for typical items
    if post_residual >= 30 && post_residual <= 70 {
        score += 6.0;
    } else if post_residual == 0 {
        score -= 15.0; // exact fill
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item can't use this residual: penalize leaving large slack
            score += post_residual as f64 * 0.05;
        }
        // Harmonic pairing: next_item class complement (next % 10 == post % 10)
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless nothing good exists
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin late in stream when open bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 && progress > 0.3 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0; // prefer filling existing bins when lookahead fits too
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
