    // residual equals the sum of the next item plus the current item's
    // size class, enabling a three-item exact closure of the bin.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == item_size && item_size <= 30 {
            score -= 28.0 * (0.5 + progress);
        }
    }

    // NEW: residual-variance budget — penalize post residuals far above the
    // fleet's mean residual only when many bins are open (fragmentation risk
    // is real); when few bins are open, large residuals are an asset.
    if post_residual > 0 && open_bins_count > 3 {
        let excess = post_residual as f64 - mean_residual;
        if excess > 0.0 {
            score += excess * 0.09 * progress;
        }
    }

    // NEW: scarcity-aware near-exact bonus — when fitting options are scarce,
    // a near-perfect fit (post residual <= 6) is worth extra to avoid
    // being forced into a fresh bin later.
    if post_residual >= 1 && post_residual <= 6 && fitting_bins_count <= 3 {
        score -= 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: superlinear penalty on unusable small gaps.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            score += 40.0 * (10.0 - pr); // tiny slivers are nearly useless
        } else if pr < 25.0 {
            score += 1.5 * (25.0 - pr); // small gaps less flexible
        }
    }

    // Reward tight fits (low waste fraction).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
