    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize mildly, but discount when lookahead won't fit
        // the residual we would leave, making opening attractive for big items.
        score += 15.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0; // new bin leaves room for the next item too
        }
        if item_size > 60 {
            score -= 10.0; // large items open fresh bins cheaply
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    if bin_residual != bin_capacity {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    score
}

