    // toward the fleet mean, improving future combinability across bins.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should never leave a mid-band residual
    // that small items would fill inefficiently; push them to near-exact fits.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — when options are few, reward the
    // bin that stays most reusable for the unknown remainder of the stream.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — in the final stretch, any nonzero residual is nearly
    // pure waste; escalate the push to close bins completely.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze — tighten the residual-variance budget
    // by rewarding placements that leave post residual close to a small
    // modular residue class (highly combinable), penalizing odd stragglers.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — when the next item is large and only
    // this bin can host both, reward keeping the post residual exactly able
    // to chain; otherwise steer the big item toward the emptiest usable bin.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum of current and next against
    // the full bin — rewards placements that set up a two-item exact closure.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — reward consuming >70% of the residual,
    // with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size
    // are prime dead space; penalize proportionally.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: dead-space budget ledger — track the fleet-wide expected waste
    // per bin via mean residual; when this placement leaves a post residual
    // that is small relative to the mean, treat the freed headroom as a
    // compaction credit, scaling with how many bins remain open.
    if post_residual > 0 && mean_residual > 0.0 {
        let headroom = (mean_residual - post_residual as f64).max(0.0);
        score -= headroom * 0.10 * (1.0 + open_bins_count as f64 * 0.05);
    }

    // NEW: last-fit dominance — when the current bin is the tightest option
    // (post residual minimal among plausible fits), amplify the tightness
    // gradient so near-closed bins win decisively over looser alternatives.
    if bin_residual < bin_capacity && post_residual > 0 && post_residual <= 6 {
        score -= (7.0 - post_residual as f64) * 9.0 * (0.6 + progress);
    }

    // NEW: oversized-item containment — when the current item is large and
    // leaves a post residual below half its size, that gap is likely unusable
    // for typical items; penalize to steer big items toward exact fits.
    if item_size > 40 && post_residual > 0 && post_residual < item_size / 2
        && next_item_size > 0 && post_residual < next_item_size {
        score += (item_size as f64 - post_residual as f64) * 0.22 * (0.5 + progress);
    }

    // NEW: combinatorial pair-availability — post residual that equals the
    // sum of two plausible small items (<= 50 each) is highly reusable;
    // reward such splits, strongest mid-stream when bins are still forming.
    if post_residual >= 4 && post_residual <= 60 {
        let half = post_residual / 2;
        if half >= 2 && post_residual - half <= 50 {
            score -= 5.0 * (0.4 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Perfect chain: next item fits exactly into the remaining space.
            let chain_gap = post_residual as f64 - nxt;
            score -= 45.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to how wasted the residual is.
            let waste_frac = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * waste_frac;
        }
    } else {
        // Last item: pure tightness preference.
        score -= 30.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // Prefer bins tighter than the mean residual (classic best-fit bias).
    score += 0.8 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64
        } else {
            1.0
        };
        score += 55.0 - 35.0 * (1.0 - poor_fit) - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        if fitting_bins_count == 1 {
            score += 120.0; // never open a new bin when this is the only fitting bin
        }
    }

    // Mild stream-progression pressure: as the stream advances, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

