    if post_residual > 0 && post_residual < bin_capacity {
        let half_split_possible = post_residual >= 2 && (post_residual / 2) * 2 == post_residual;
        let next_closes = next_item_size > 0 && post_residual >= next_item_size;
        if !half_split_possible && !next_closes {
            score += 7.0 * (0.5 + progress);
        }
    }

    // Mean-residual gap targeting — steer post residual toward the fleet mean.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should never leave a mid-band residual.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — keep scarce bins most reusable.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — final stretch, any nonzero residual is nearly pure waste.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space-ratio quadratic refinement fused with slack-sharpness gradient.
    if post_residual > 0 {
        let dr = post_residual as f64 / bin_capacity as f64;
        let hostable = next_item_size > 0 && post_residual >= next_item_size;
        let small_hostable = post_residual <= 12;
        if !hostable && !small_hostable {
            score += dr * dr * 60.0 * (0.4 + progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 / (1.0 + slack * 0.35)) * 20.0 * (0.5 + progress);
    }

    // Near-closure trap guard fused with residual-band reusability.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 6 {
        score += 25.0 + 20.0 * progress;
    }
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 7 == 0)
        && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Lookahead tight-fit coupling with scarcity amplification.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 18.0;
        }
    }

    // Dead-space variance squeeze — modular residue class alignment.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling for large next items.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-combinability index — reward post residuals expressible
    // as sums of common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
        if combinable {
            score -= 7.0 * (0.5 + progress);
        }
    }

    // Slack-variance squeeze — sharpen preference toward the bin whose post
    // residual best matches the mean residual when many bins fit.
    if fitting_bins_count > 2 && post_residual > 0 && bin_residual < bin_capacity {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.10 * progress;
    }

    // Triple-fill exact anticipation — current + next leaves a residual
    // equal to a plausible third item, enabling full closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // New-bin gating refinement — block fresh bins on near-exact existing fits.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size >= 90 {
        score += 40.0;
    }

    // NEW: residual-decay gradient — reward consuming >70% of the residual,
    // escalating as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // NEW: stranded-gap arithmetic guard — 31-59 band residuals the next item
    // cannot use and exceeding twice its size are prime dead space.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // NEW: two-item sum closure — post residual closable by next item plus a
    // small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: classify dead space
    // by modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class: which quarter of the capacity does the post residual fall in?
    let quarter = (post_residual / (bin_capacity / 4).max(1)) as u32; // 0..=4
    match quarter {
        0 => score -= 30.0,             // near-perfect fit: reward heavily
        1 => score -= 12.0,             // still quite good
        2 => score += 5.0,              // half-full residual: mildly penalize
        3 => score += 15.0,             // large dead space
        _ => score += 25.0,             // nearly untouched bin: wasteful
    }

    // Modulo structure on post_residual: residues divisible by common item
    // sizes (10, 20, 25) are re-usable, others are dead space.
    let res = post_residual;
    if res > 0 {
        let reusable = res % 10 == 0 || res % 20 == 0 || res % 25 == 0;
        if reusable {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Very small odd residual (< 10) is likely unusable dead space.
        if res < 10 {
            score += 14.0;
        }
    }

    // Integer-division threshold: does the NEXT item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic compatibility: next item leaves another clean residue class.
        let next_res = post_residual - next_item_size;
        let harmony = if next_res % 10 == 0 { 10.0 } else { 4.0 };
        score -= harmony;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how far off.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // Crowding bonus: more alternatives means we can afford to be picky;
        // penalize bins whose residual class is far from the item size class.
        let item_class = item_size / 10;
        let res_class = post_residual / 10;
        if res_class > item_class * 3 {
            score += 4.0;
        }
    }

    // New-bin candidate handling: empty bin starts neutral; only prefer it
    // when open bins are globally full and stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fullness = 1.0 - (mean_residual / cap);
        score = cap * 0.55 + fullness * 20.0 - progress * 10.0;
        // If any existing bin gives a near-perfect fit, discourage new bin.
        if post_residual == 0 && item_size < bin_capacity {
            score += 40.0;
        }
    }

    // Mild global pressure: many open bins -> prefer tighter fits.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1250.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 115.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 58.0;
        } else if post_residual < 18 {
            score += 23.0;
        } else if post_residual < 35 {
            score += 7.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 82.0 - slack * 0.7;
            if slack <= 3 {
                score -= (4.0 - slack) * 7.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.0;
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 172.0;
    }

