    }

    // Exact-fit dominance — item nearly fills the bin residual exactly.
    if bin_residual >= item_size && bin_residual - item_size <= 2 && bin_residual < bin_capacity {
        score -= 26.0;
    }

    // New-bin guard for small items — opening a bin for a small item when
