    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size <= 30 {
        score += (30 - item_size) as f64 * 1.5;
    }

    // Near-closure bonus scaled by open-bin pressure.
    if post_residual > 0 && post_residual <= 6 {
