        }
    }

    // GEN 20: dead-space ratio sharpening — post residual that is a
    // small fraction of the next item is nearly-certain waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.5 {
