    }

    // GEN 20: new-bin acceptance with lookahead trade-off.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 22.0 + 30.0 * progress;
        }
    }

    // GEN 20: residual-chain harmony — post residual equal to the
    // sum of the next item and a plausible third small item (<= 20).
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 9.0 * (0.6 + progress);
        }
    }

    // GEN 29 MUTATION A: residual-decay gradient — reward consuming >70% of
    // the bin residual, escalating as the consumed fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 52.0 * (0.5 + progress);
        }
    }

    // GEN 29 MUTATION B: pair-sum exact closure against full bin — a
    // placement setting up a two-item exact fill of a fresh bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // GEN 29 MUTATION C: mean-residual gap targeting — steer post residual
    // toward the fleet mean to improve future combinability across bins.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // GEN 29 MUTATION D: large-item gating — big items should never leave a
    // mid-band residual that small items would fill inefficiently.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // GEN 29 MUTATION E: endgame sweep — in the final stretch, any nonzero
    // residual is nearly pure waste; escalate the push to close bins.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // GEN 29 MUTATION F: lookahead-scarcity coupling — when the next item is
    // large, reward keeping the post residual able to chain it.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // GEN 29 MUTATION G: stranded-gap arithmetic guard — residuals in the
    // 31-59 band the next item cannot use and that exceed twice its size.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // GEN 29 MUTATION H: new-bin parity refinement — when opening a fresh
    // bin is the only option, prefer it early (residual stays maximal).
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // GEN 29 MUTATION I: fine-grained fit + lookahead synthesis — when the
    // post residual exactly matches the next item AND the consumed fraction
    // of the bin is high, grant a compounding closure reward.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual >= item_size {
        let consumed_frac = item_size as f64 / bin_residual.max(1) as f64;
        if consumed_frac > 0.75 {
            score -= (consumed_frac - 0.75) * 60.0 * (0.4 + progress);
        }
    }

    // GEN 29 MUTATION J: modular-combinability squeeze — post residuals
    // divisible by 3 or 5 combine well with future small items; odd
    // stragglers in the 13-29 band are prime waste.
    if post_residual > 12 && post_residual < 30 {
        if post_residual % 3 == 0 || post_residual % 5 == 0 {
            score -= 5.0 * (0.4 + progress);
        } else {
            score += 6.0 * (0.4 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1250.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 115.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 60.0;
        } else if post_residual < 18 {
            score += 24.0;
        } else if post_residual < 35 {
            score += 7.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 85.0 - slack * 0.7;
            if slack <= 3 {
                score -= (4.0 - slack) * 7.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.0;
            if post_residual < 10 {
                score += 32.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 175.0;
    }

