    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 16.0;
    }

    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.9;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate: attractive only when no alternative exists.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -38.0
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -26.0
        } else {
            105.0 + open_bins_count as f64 * 2.2
        };
        score += penalty;
    }

    // Residual balancing: prefer bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else if post_residual as f64 > mean_residual + 18.0 {
        score += (post_residual as f64 - mean_residual - 18.0) * 0.4;
    }

    // Progress-driven tightness.
    let tightness = if progress < 0.15 { 0.18 } else { 0.11 * (1.0 + progress) };
    score -= (bin_capacity - post_residual) as f64 * tightness;

    // Chain potential: post residual can host next item with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        if chain_slack > 0 && chain_slack <= 12 {
            score -= 15.0;
        }
    }

    // Anti-fragmentation: residual equal to item size stays reusable.
    if post_residual > 0 && post_residual == item_size {
        score -= 20.0;
    }

    // Awkward-residual trap: 20-45 band unusable by next item.
    if post_residual >= 20 && post_residual <= 45 && next_item_size > post_residual {
        score += 12.0;
    }

    // Late-stream consolidation: fill existing bins almost completely.
    if progress > 0.7 && post_residual > 0 && post_residual < 25 {
        score -= 9.0 * progress;
    }

    // Exact-pair anticipation: two identical items exactly fill the bin.
    if next_item_size > 0 && next_item_size == item_size && item_size * 2 == bin_residual {
        score -= 45.0;
    }

    // Mid-stream selection sharpening: many fitting bins -> prefer emptiest.
    if fitting_bins_count > 2 && bin_residual < bin_capacity {
        score += (bin_residual as f64) * 0.05;
    }

    // Reusable-residual harmony — post residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 24.0;
    }

    // Small-item sink — tiny items go into the smallest usable gap.
    if item_size <= 10 && post_residual > 0 && post_residual < 30 {
        score -= 16.0;
    }

    // Three-step viability — post residual hosts next item leaving a small residual.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 12 && next_item_size >= r2 {
            score -= 10.0;
        }
    }

    // Avoid leaving residuals in the 61-99 band when next item cannot use them.
    if post_residual >= 61 && post_residual <= 99 && next_item_size > post_residual {
