    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no item can realistically fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Extra penalty when post_residual is small but nonzero relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    if tightness > 0.0 && tightness < 0.1 {
        score += 15.0 * (0.1 - tightness) / 0.1;
    }

    // Reward nearly-full bins (waste minimization).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild preference toward bins with lower residual than mean (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream conservatism: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate: make empty bins mildly attractive only when residuals are fragmented.
    if bin_residual == bin_capacity {
        if mean_residual < 5.0 {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    score
}

