pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: favor tight fits (small post_residual), scaled by capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect chain fit gets a big bonus.
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Penalize wasted gap between post_residual and next item.
                score += 0.8 * gap;
            }
        } else {
            // Next item cannot fit here; mildly penalize small leftovers.
            score += 0.3 * pr;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (closing down "nearly full" bins), penalize placing into above-average bins.
    let res = bin_residual as f64;
    score += 0.4 * (res - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current
    // item nearly fills it. Penalize the empty-bin candidate generally.
    if bin_residual == bin_capacity {
        // A fresh bin is only attractive if the item leaves a residual that the
        // next item can exactly consume, or the stream is early and we need bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 3.0 {
            score -= 55.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if progress < 0.1 {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins in the later part of the stream (reduce spread).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

