    // Stranded-gap arithmetic guard — residuals in the 31-59 band that the
    // next item cannot use and that exceed twice the next item's size are
    // prime dead space; penalize proportionally to how unreachable they are.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item plus a
    // small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only option,
    // prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: residual-variance homogenization — when many bins fit, steer all
    // post residuals toward the fleet mean so future items have uniform
    // combinable gaps; penalize outliers in either direction.
    if post_residual > 0 && fitting_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev > 15.0 {
            score += (dev - 15.0) * 0.35 * (0.4 + progress);
        } else {
            score -= (15.0 - dev) * 0.12;
        }
    }

    // NEW: next-item residual handoff — when the next item exactly consumes
    // the post residual, the bin closes with zero waste; escalate the reward
    // as the stream progresses since early closure compounds savings.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        score -= 18.0 * (0.5 + progress);
    }

    // NEW: overshoot-avoidance for small items — tiny items placed into large
    // residuals strand most of the gap; nudge them toward the tightest gap
    // unless the leftover remains broadly reusable.
    if item_size <= 20 && post_residual > 40 && next_item_size > 0
        && post_residual < next_item_size {
        score += (post_residual as f64) * 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual dominates).
    score += (post_residual as f64 / bin_capacity as f64).powf(3.0) * 60.0;

    // Perfect fit is nearly free.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // When many bins fit the item, prefer the one with the smallest residual
    // (best-fit bias), scaled by competition.
    if fitting_bins_count > 1 {
        score += (bin_residual as f64) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Penalize post-residuals that are too small for the next item (dead space),
    // but only mildly since the next item may go elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += post_residual as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the empty bin proportionally to how much
    // residual already exists across open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
        // Late in the stream, opening new bins is less costly (fewer future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild global pressure: with many open bins, tighten packing (avoid waste).
    score += mean_residual * 0.05;

    // Slight preference for bins with larger residual absorbing big items.
    score -= (item_size as f64) * (bin_residual as f64 / bin_capacity as f64) * 0.1;

    score
}

