        }
    }

    // NEW: next-item exact-chain bonus sharpening — when the next item would
    // leave only a tiny (<=4) remainder after this placement, treat it as
    // an almost-closed bin and reward it strongly.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 4 {
            score -= 20.0 + 8.0 * progress;
        }
    }

    // NEW: mid-stream dead-band squeeze — residuals in the 21-29 band are
    // the hardest to combine; penalize them extra when alternatives exist.
    if post_residual >= 21 && post_residual <= 29 && fitting_bins_count > 1 {
        score += 9.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild preference for tight fits; late: strong preference (waste compounds).
    let tightness = 1.0 - pr / cap; // in (0,1], higher = tighter fit
    let coupling = pr * pr / cap * (0.5 + 2.5 * progress * progress);
    score += coupling * 0.1;

    // Reward very tight fits with a smooth non-linear term.
    score -= 12.0 * (1.0 - tightness).powi(3) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: penalize if next item cannot fit the post-residual (dead space risk).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 6.0 + 8.0 * (nxt - pr) / cap;
        } else {
            // Reward leaving space usable by the next item.
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Penalize opening a new bin when open bins exist and fit is decent,
    // but allow it when residual space is large and fragmented (mean residual high).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * fragmentation * fragmentation + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure against proliferating many open bins early on.
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 1.5;

    // Smooth waste penalty: leftover space below typical next-item size is dead.
    let dead = (pr / cap).powi(4);
    score += 15.0 * dead;

    score
}

