        }
    }

    // New-bin gating refinement — block fresh bins when a near-exact fit exists.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size >= 90 {
        score += 40.0;
    }

    // MUTATION: residual-decay gradient — reward consuming >70% of residual,
    // escalating as the fraction approaches 1 (fine-grained fitting).
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // MUTATION: stranded-gap arithmetic guard — 31-59 band residuals that the
    // next item cannot use and exceed twice its size are prime dead space.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // MUTATION: two-item sum closure — post residual closeable by next item
    // plus a small follow-up in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // MUTATION: new-bin parity refinement — prefer fresh bins early, not late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // MUTATION: lookahead-fit fusion — couple consumed fraction with next-item
    // hostability: a tight fit that still hosts the next item is doubly good.
    if next_item_size > 0 && bin_residual > item_size && bin_residual < bin_capacity {
        let left = bin_residual - item_size;
        if left >= next_item_size {
            let tight = 1.0 - (left - next_item_size) as f64 / bin_capacity as f64;
            score -= tight * 10.0 * (0.4 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "dead zone" (too small for the smallest plausible item) are penalized.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold && post_residual > 0 {
        // Dead space: leftover too small for any item (min size 1..100 unknown,
        // so use a graded penalty based on how close to zero it is).
        score += (dead_threshold as f64 - post_residual as f64) * 2.5;
    }

    // Perfect fit reward: no waste at all.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: post_residual modulo capacity quarters — leftovers in
    // the quarter classes are more reusable than thirds-of-a-class fragments.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => score -= 5.0,                 // tiny leftover: likely dead space, but handled above
        1 => score -= 12.0,                // quarter-class: very reusable
        2 => score -= 8.0,                 // half-class: reusable
        3 => score -= 10.0,                // three-quarter class: good
        _ => {}                            // full/empty bin class
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-fit: excellent, deeper reward for tighter chains.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 + 15.0 * chain_tightness;
        } else {
            // Next item won't fit: penalize proportionally to the overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // fallback unless the current fit is terrible. Penalize opening new bins
    // mildly, more so early in the stream when bins are cheap to fill.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 35.0 + 20.0 * (1.0 - progress) - 5.0 * openness;
    } else {
        // Prefer fuller bins: reward small residuals relative to mean.
        if mean_residual > 0.0 {
            let rel = bin_residual as f64 / mean_residual;
            if rel < 1.0 {
                score -= 8.0 * (1.0 - rel);
            } else {
                score += 4.0 * (rel - 1.0);
            }
        }
    }

    // Integer-division threshold on post_residual: leftovers below half the
    // smallest common item class are risky.
    if post_residual > 0 && post_residual < bin_capacity / 8 {
        score += 15.0;
    }

    score
}

