    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should never leave a mid-band residual
    // that small items would fill inefficiently; push them to near-exact fits.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — when options are few, reward the
    // bin that stays most reusable for the unknown remainder of the stream.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — in the final stretch, any nonzero residual is nearly
    // pure waste; escalate the push to close bins completely.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze — tighten the residual-variance budget
    // by rewarding placements that leave post residual close to a small
    // modular residue class (highly combinable), penalizing odd stragglers.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — when the next item is large and only
    // this bin can host both, reward keeping the post residual exactly able
    // to chain; otherwise steer the big item toward the emptiest usable bin.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum of current and next against
    // the full bin — rewards placements that set up a two-item exact closure.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — reward consuming >70% of the residual with
    // an escalating bonus as the fraction approaches 1; sharpened by stream
    // position so mid/late compaction is preferred.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 62.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that the
    // next item cannot use and that exceed twice the next item's size are
    // prime dead space; penalize proportionally to how unreachable they are.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item plus
    // a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: dead-space budget accounting — track the fleet-wide waste implied
    // by leaving this residual stranded. When the post residual exceeds what
    // any remaining stream volume plausibly needs (mean item scale proxy via
    // next item), penalize the gap proportionally to open-bin competition:
    // with many open bins, a stranded gap is less likely to ever be filled.
    if post_residual > 0 && bin_residual < bin_capacity {
        let competition = (open_bins_count as f64).min(12.0) / 12.0;
        let stranded_risk = post_residual as f64 * competition;
        let next_usable = next_item_size > 0 && post_residual >= next_item_size;
        if !next_usable {
            score += stranded_risk * 0.5 * (0.4 + progress);
        } else {
            // Reward keeping a residual exactly one future item wide when
            // competition is high — it converts dead space into scheduled fill.
            let exact_chain = (post_residual == next_item_size) as f64;
            score -= exact_chain * 10.0 * competition * (0.5 + progress);
        }
    }

    // NEW: residual-fraction compaction — prefer placements whose post
    // residual is a small fraction of the original residual, with a graded
    // bonus that sharpens as the fraction shrinks below 0.35.
    if bin_residual > 0 && bin_residual < bin_capacity && post_residual > 0 {
        let frac = post_residual as f64 / bin_residual as f64;
        if frac < 0.35 {
            score -= (0.35 - frac) * 40.0 * (0.6 + progress);
        }
    }

    // NEW: new-bin opening gate with capacity headroom — a fresh bin should
    // only win when existing residuals are too fragmented to combine; scale
    // the penalty by how much total residual space already exists per open bin.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let avg_residual = mean_residual.max(1.0);
        let fragmentation = avg_residual / bin_capacity as f64;
        score += fragmentation * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
