    }

    // Triple-fill lookahead — residual after next item matches a small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 25 && r2 >= item_size / 4 {
            score -= 12.0;
        }
    }

    // Divisibility harmony — clean multiples likely exactly filled later.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 || r % 5 == 0 {
            score -= 5.0;
        }
        if r > 50 && r % 25 == 0 {
            score -= 8.0;
        }
    }

    // Dead-space trap quantization — residuals that no item of size 1..=100
    // can split into two future fills are prime waste; scale penalty by progress.
    if post_residual > 0 && post_residual < bin_capacity {
        let half_split_possible = post_residual >= 2 && (post_residual / 2) * 2 == post_residual;
        let next_closes = next_item_size > 0 && post_residual >= next_item_size;
        if !half_split_possible && !next_closes {
            score += 7.0 * (0.5 + progress);
        }
    }

    // Mean-residual gap targeting — prefer placements steering post residual
    // toward the fleet mean, improving future combinability across bins.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should never leave a mid-band residual
    // that small items would fill inefficiently; push them to near-exact fits.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — when options are few, reward the
    // bin that stays most reusable for the unknown remainder of the stream.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — in the final stretch, any nonzero residual is nearly
    // pure waste; escalate the push to close bins completely.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze — tighten the residual-variance budget
    // by rewarding placements that leave post residual close to a small
    // modular residue class (highly combinable), penalizing odd stragglers.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — when the next item is large and only
    // this bin can host both, reward keeping the post residual exactly able
    // to chain; otherwise steer the big item toward the emptiest usable bin.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum of current and next against
    // the full bin — rewards placements that set up a two-item exact closure.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — reward consuming >70% of the residual,
    // with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size
    // are prime dead space; penalize proportionally to how unreachable.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // GEN 32 MUTATION: fine-grained fit + lookahead synergy — when the item
    // nearly exhausts the residual AND the leftover exactly hosts the next
    // item, this is a two-item closure; reward proportionally to fit quality.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        score -= fq * 45.0;
    }

    // GEN 32 MUTATION: fragmentation trap — post residual just below next item
    // (off-by-small gap) is the worst kind of dead space; penalize harder when
    // few alternatives exist to absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8 {
            score += (8.0 - gap) * 3.5 * (1.0 + progress);
        }
    }

    // GEN 32 MUTATION: scarce-alternative tightening — when only one or two
    // bins can host the next item, protect bins that keep that possibility.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }

    // GEN 32 MUTATION: dual residual divisibility — post residual divisible by
    // both 3 and next item size suggests a clean multi-item closure chain.
    if next_item_size > 2 && post_residual > 0 && post_residual % next_item_size == 0
        && post_residual % 3 == 0 {
        score -= 6.0;
    }

    // GEN 32 MUTATION: late-stream small-residual closure race — near the end,
    // prefer bins whose post residual is the smallest achievable.
    if progress > 0.8 && post_residual > 0 && post_residual <= 5 {
        score -= 15.0 * (progress - 0.8) * 5.0;
    }

    // GEN 32 MUTATION: high-fit-quality compaction — reward placements with
    // fit quality above 0.9 that also keep the next item chainable, scaled by
    // fitting scarcity (combines fine-grained fitting with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        if fq > 0.9 {
            score -= (fq - 0.9) * 100.0 * (1.0 - progress * 0.3);
        }
        if fitting_bins_count > 3 {
            score -= 6.0;
        }
    }

    // GEN 32 MUTATION: dead-space ratio sharpening — post residual that is a
    // small fraction of the next item is nearly-certain waste; penalize
    // proportionally to the unusable fraction and open-bin pressure.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.5 {
            score += (0.5 - unusable) * 30.0 * (0.6 + progress)
                + open_bins_count as f64 * 0.4;
        }
    }

    // GEN 32 MUTATION: new-bin acceptance with lookahead trade-off — opening a
    // fresh bin is acceptable only when the item is large and the next item
    // would strand no existing residual; otherwise penalize with a
    // progress-scaled barrier.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 22.0 + 30.0 * progress;
        }
    }

    // GEN 32 MUTATION: residual-chain harmony — post residual equal to the
    // sum of the next item and a plausible third small item (<= 20) closes
    // the bin in two more steps; reward scaled by progress.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 9.0 * (0.6 + progress);
        }
    }

    // GEN 32 MUTATION: exact-multiple chain — post residual being a small
    // multiple of the next item enables repeated exact closures.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let r = post_residual % next_item_size;
        if r == 0 && post_residual / next_item_size <= 4 {
            score -= 14.0;
        } else if r <= 2 {
            score -= 7.0;
        }
    }

    // GEN 32 MUTATION: residual-continuity lookahead — post residual hosts the
    // next item AND the leftover r2 sits between half and full next item size
    // (keeps both items of a future pair placeable).
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 >= next_item_size && r2 <= next_item_size {
            score -= 9.0 * (1.0 - progress * 0.4);
        }
    }

    // GEN 32 MUTATION: exact-fit dominance — item nearly fills the bin
    // residual exactly; strongly prefer over leaving a hairline gap.
    if bin_residual >= item_size && bin_residual - item_size <= 2 && bin_residual < bin_capacity {
        score -= 26.0;
    }

    // GEN 32 MUTATION: next-item stranding guard refinement — when the next
    // item cannot fit the post residual but CAN fit another bin, penalize
    // proportionally to the wasted gap, scaled by stream position.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.9 * (0.4 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (2-step lookahead match).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 0.25 * gap;
        }
    } else {
        // Last item: reward tight fits harder.
        score *= 1.2;
    }

    // Reward leaving no dead space (perfect fill).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Prefer bins with residuals below the mean residual (tighter bins get priority),
    // penalize wasting space in loose bins relative to mean.
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it is only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.1 * open_bins_count as f64;
    }

    score
}

