    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste in post-residual
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, residual waste matters more (quartic ramp)
    let ramp = progress * progress * progress * (1.0 + 3.0 * progress);
    score += ramp * pr * pr / cap * 2.0;

    // Reward tight fits: subtract for small normalized post-residual
    let tight = 1.0 - (pr / cap);
    score -= 30.0 * tight * tight * tight;

    // Lookahead coupling: bonus if next item fits into the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // smooth reward proportional to how well next item fills the gap
            let fill = nxt / pr.max(1.0);
            score -= 25.0 * fill * (1.0 - (pr - nxt) / cap);
        } else {
            // next item too big for this residual: mild penalty scaled by overshoot
            let over = (nxt - pr) / cap;
            score += 15.0 * over * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: prefer the fullest one; penalize bins far from mean residual
    if fitting_bins_count > 1 {
        score += 5.0 * ((pr - mean_residual) / cap).abs();
    }

    // New-bin candidate: neutral-ish baseline, penalized early, relaxed late
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score = 60.0 * openness + 20.0;
        // allow new bins late if item is huge relative to typical residual
        score -= 0.5 * item_size as f64 * progress;
    }

    // Mild penalty for accumulating many open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

