pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals near multiples of common
    // item sizes (10..80 grid) are more reusable; reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity filled by this placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill ratio (non-linear, harmonic emphasis).
    score -= 40.0 * fill * fill;

    // Harmonic classes: post_residual divisible by small common sizes
    // (10, 20, 25, 50) leaves reusable chunks.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect close
    } else {
        let mut reuse_bonus = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if pr % m == 0 && pr >= m {
                reuse_bonus += 8.0;
            }
        }
        // Integer-division threshold: small dead space is bad.
        if pr < 10 {
            score += 25.0; // unusable dead space
        } else if pr <= 30 {
            score -= reuse_bonus; // fits many typical small items
        } else {
            score -= reuse_bonus * 0.5;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            score += 6.0; // next item won't fit here; this bin is a dead end
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin if all open bins
    // would leave tiny unusable residuals.
    if bin_residual == bin_capacity {
        // neutral base; penalize when open bins can handle item decently
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible >= 10.0 {
                score += 30.0; // discourage new bin when a decent fit exists
            }
        }
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.5 * mean_residual / (open_bins_count.max(1) as f64);

    // Stream-phase modulation: later in stream, prefer tighter packing.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * phase * fill;

    score
}

