            // Next item fits: penalize leftover double-residual (waste after 2 items)
            score -= 0.5 * (post_residual - next_item_size) as f64;
            score += 0.3 * (post_residual - next_item_size) as f64 * (post_residual - next_item_size) as f64 / 100.0;
