        }
    }

    // GEN 33 MUTATION: fine-grained lookahead compaction — when the post
    // residual hosts the next item with high fit quality, reward the chain
    // scaled by fitting scarcity (combines best-fit with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        if fq > 0.85 {
