    // item (off-by-small gap) is the worst dead space; penalize harder when
    // few alternatives exist to absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8 {
            score += (8.0 - gap) * 3.5 * (1.0 + progress)
                + (fitting_bins_count <= 2) as i32 as f64 * 8.0;
        }
    }

    // GEN 33 MUTATION: multi-item closure chain — post residual is a small
    // multiple of the next item size (exact chain packing for 2-4 items).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let r = post_residual % next_item_size;
        if r == 0 && post_residual / next_item_size <= 4 {
