    // a fresh bin is acceptable only for large items that the next item can
    // also follow into; otherwise penalize with a progress-scaled barrier.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 22.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
