    // baseline's implicit weighting with an explicit waste-fraction term:
    // the stranded share of the bin's capacity, amplified by lookahead
    // infeasibility, directly targets the diagnosed dead-space weakness.
    if post_residual > 0 && bin_residual < bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        let next_cannot_use = next_item_size == 0 || post_residual < next_item_size;
        let ampl = if next_cannot_use { 1.6 } else { 0.7 };
        score += waste_frac * 42.0 * ampl * (0.55 + progress);
    }

