    // fleet mean, it is likely to be matched by another bin's leftover;
    // reward such small, mean-attracted residuals to encourage cross-bin
    // combinability instead of isolated dead space.
    if post_residual > 0 && (post_residual as f64) < mean_residual && post_residual >= 5 {
        score -= (mean_residual - post_residual as f64).min(30.0) * 0.35;
    }

