    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // Residual-variance squeeze continuation — penalize residuals that are
    // simultaneously too small for the next item AND below the mean residual
    // (doubly stranded fragments).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // Near-exact chain — reward when the current item leaves a post
    // residual that the next item can consume almost exactly (slack <= 2),
    // extending the chain potential into a tighter band.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // Mid-band residual consolidation — residuals in the 26-40 band are
    // the most common source of waste; when multiple bins fit, prefer the one
    // that escapes this band entirely (post residual 0 or >= 41).
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // New-bin threshold refinement — opening a fresh bin is only worth
    // it when the best alternative would strand a large fraction of residual;
    // scale the fresh-bin penalty by how much dead space the alternatives leave.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // GEN 34 MUTATION: consumed-fraction compaction with lookahead coupling —
    // reward placements that both consume a very high fraction of the residual
    // AND leave a post residual the next item can chain into, scaled by
    // fitting scarcity (combining fine-grained fitting with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size
        && bin_residual < bin_capacity {
        let fq = item_size as f64 / bin_residual as f64;
        if fq > 0.85 {
            let scarcity = if fitting_bins_count <= 2 { 1.5 } else { 1.0 };
            score -= (fq - 0.85) * 70.0 * scarcity * (0.6 + progress * 0.5);
        }
    }

    // GEN 34 MUTATION: off-by-small fragmentation trap — a post residual just
    // below the next item size (gap <= 6) is near-certain waste when few
    // alternatives exist to absorb the next item; penalize sharply.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += (6 - gap) as f64 * 4.0 * (0.8 + progress);
        }
    }

    // GEN 34 MUTATION: exact-closure ladder — post residual exactly matches
    // the next item OR the next item plus a tiny follow-up (<= 4); these
    // two-step closures are the cheapest way to eliminate dead space.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 4 {
            score -= 20.0 * (0.7 + progress);
        }
    }

    // GEN 34 MUTATION: new-bin acceptance with lookahead trade-off — opening
    // a fresh bin is acceptable only for large items whose next-item pairing
    // would strand no residual; otherwise penalize with a progress-scaled barrier.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 16.0 * (1.0 - progress);
        } else {
            score += 24.0 + 32.0 * progress;
        }
    }

    // GEN 34 MUTATION: residual-halving harmony — a second identical item
    // exactly closes what remains, or the post residual is half the next item
    // size (two-step closure with a duplicate next item).
    if post_residual > 0 && next_item_size > 0 && post_residual * 2 == next_item_size {
        score -= 10.0 * (0.6 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
