        } else if !three_item {
            // Only a single item of exactly size r can ever close this bin:
            // strong dead-space penalty scaled by how much capacity is stranded.
            score += (r as f64 / bin_capacity as f64) * 30.0 * (0.6 + progress);
        }
        // Exact-match anticipation: residual in the dense small-item mass
        // region (most frequent sizes) is likely closed by a future item.
        if r >= 20 && r <= 50 {
