        }
    }

    // NEW: new-bin opening gate — open a fresh bin only when every existing
    // alternative would strand substantial dead space. Estimate the minimum
    // stranded waste across fitting bins via mean residual; if the item would
    // leave the fresh bin nearly full of reusable space relative to the
    // alternatives, tip the balance toward opening it; otherwise suppress.
