        let waste_delta = existing_post_est - fresh_post;
        if waste_delta > 15.0 {
            // Existing bins would strand much more: opening is competitive.
            score -= (waste_delta - 15.0) * 0.8;
        } else {
            // Fresh bin wastes more: suppress proportional to the deficit,
            // stronger late in the stream when bins are scarcer to close.
            score += (15.0 - waste_delta.max(0.0)) * 0.5 * (0.5 + progress);
        }
    }

    score
}

