    // Fit-margin sharpening — near-exact fits minimize residual variance.
    if post_residual > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        if slack <= 5 {
            score -= (6.0 - slack as f64) * 6.0;
        }
    }

    // Next-item stranding guard — prefer alternatives that can host next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // Stranding-risk coupling — waste scaled by progress.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.9 * (0.4 + progress);
    }

    // Exact-fit chain anticipation — next item exactly closes what remains.
    if next_item_size > 0 && post_residual > 0 && post_residual == next_item_size {
        score -= 30.0 * (0.5 + progress);
    }

    // Dual-fit lookahead — r2 == next item closes the bin on third placement.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 26.0;
        }
    }

    // Residual-band discrimination — rarely-usable 13-19 band penalized.
    if post_residual >= 13 && post_residual <= 19
        && next_item_size > post_residual && fitting_bins_count > 1 {
        score += 10.0 + 4.0 * progress;
    }

    // Compaction pressure scaled by stream length and position.
    let stream_scale = 1.0 + (total_items as f64).ln().max(1.0) * 0.05;
    if post_residual > 0 {
        score += (post_residual as f64) * 0.04 * stream_scale * (0.3 + progress);
    }

    // Open-bin economy — few bins open: keep residuals large and reusable.
    if open_bins_count <= 3 && post_residual > 40 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Graded near-perfect band late in stream.
    if post_residual >= 5 && post_residual <= 10 && progress > 0.5 && item_size >= post_residual / 2 {
        score -= 24.0 * progress;
    }

    // New-bin deferral — late in stream, strongly discourage fresh bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.6 {
        score += 60.0 * progress;
    }

    // Early-stream exploration — keep large residuals available.
    if progress < 0.3 && post_residual < 40 && item_size < 40 {
        score += 6.0;
    }

    // Reusability dead-space ratio scaled by progress.
    if post_residual > 0 && next_item_size > 0 {
        let reusability = if post_residual >= next_item_size { 0.0 }
            else if post_residual >= next_item_size / 2 { 8.0 }
            else { 20.0 };
        score += reusability * (0.5 + progress);
    }

    // Open-bin consolidation — many bins open: close hardest bins first.
    if open_bins_count > 4 && bin_residual < bin_capacity && post_residual > 0 {
        score += (post_residual as f64) * 0.06;
    }

    // Triple-fill lookahead — residual after next item matches a small item.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 25 && r2 >= item_size / 4 {
            score -= 12.0;
        }
    }

    // Divisibility harmony — clean multiples likely exactly filled later.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 || r % 5 == 0 {
            score -= 5.0;
        }
        if r > 50 && r % 25 == 0 {
            score -= 8.0;
        }
    }

    // Dead-space trap quantization — residuals that no item of size 1..=100
    // can split into two future fills are prime waste; scale penalty by progress.
    if post_residual > 0 && post_residual < bin_capacity {
        let half_split_possible = post_residual >= 2 && (post_residual / 2) * 2 == post_residual;
        let next_closes = next_item_size > 0 && post_residual >= next_item_size;
        if !half_split_possible && !next_closes {
            score += 7.0 * (0.5 + progress);
        }
    }

    // Mean-residual gap targeting — prefer placements steering post residual
    // toward the fleet mean, improving future combinability across bins.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.06;
    }

    // Large-item gating — big items should never leave a mid-band residual
    // that small items would fill inefficiently; push them to near-exact fits.
    if item_size > 60 && post_residual > 0 && post_residual < 30 {
        score += 20.0;
    }

    // Fitting-count scarcity bonus — when options are few, reward the
    // bin that stays most reusable for the unknown remainder of the stream.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — in the final stretch, any nonzero residual is nearly
    // pure waste; escalate the push to close bins completely.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze — tighten the residual-variance budget
    // by rewarding placements that leave post residual close to a small
    // modular residue class (highly combinable), penalizing odd stragglers.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — when the next item is large and only
    // this bin can host both, reward keeping the post residual exactly able
    // to chain; otherwise steer the big item toward the emptiest usable bin.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum of current and next against
    // the full bin — rewards placements that set up a two-item exact closure.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — post residual should shrink aggressively
    // toward zero relative to what was available; reward consuming >70% of the
    // residual, with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size are
    // prime dead space; penalize proportionally to how unreachable they are.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // Residual-variance squeeze continuation — sharpen the dead-space
    // diagnosis by penalizing residuals that are simultaneously too small for
    // the next item AND below the mean residual (doubly stranded fragments).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // Near-exact chain — reward when the current item leaves a post
    // residual that the next item can consume almost exactly (slack <= 2),
    // extending the parent's chain potential into a tighter band.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // Mid-band residual consolidation — residuals in the 26-40 band are
    // the most common source of waste; when multiple bins fit, prefer the one
    // that escapes this band entirely (post residual 0 or >= 41).
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // New-bin threshold refinement — opening a fresh bin is only worth
    // it when the best alternative would strand a large fraction of residual;
    // scale the fresh-bin penalty by how much dead space the alternatives leave.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // MUTATION 1: dead-space ratio is the diagnosed weakness — replace the
    // flat stranded penalty with a convex (squared) form so that large
    // stranded fractions are punished much more aggressively, and couple it
    // to fitting scarcity (when few bins can host the item, waste matters
    // less because there is no better choice).
    if post_residual > 0 && post_residual < bin_capacity {
        let stranded = post_residual as f64 / bin_capacity as f64;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        let reusable_band = post_residual <= 12 || post_residual % 5 == 0;
        if !usable_by_next && !reusable_band {
            let scarcity_relief = 1.0 - (fitting_bins_count.min(4) as f64) * 0.12;
            score += stranded * stranded * 190.0 * (0.5 + progress) * scarcity_relief;
        }
    }

    // MUTATION 2: quadratic consumed-fraction reward — extend the linear
    // residual-decay gradient into a convex escalation so near-exact fits
    // (consumed fraction near 1) dominate, directly attacking dead space.
    if bin_residual > 0 && bin_residual < bin_capacity && item_size > 0 {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            let excess = consumed - 0.7;
            score -= (excess * excess * 160.0 + excess * 40.0) * (0.5 + progress);
        }
    }

    // MUTATION 3: waste-budget lookahead — estimate the total dead space of
    // this placement (post residual minus what next item could absorb) and
    // penalize it proportionally, sharpening the stranding-risk coupling
    // which previously used only the raw gap.
    if next_item_size > 0 && post_residual > 0 {
        let absorbable = post_residual.min(next_item_size);
        let dead = (post_residual - absorbable) as f64;
        if dead > 0.0 {
            score += dead * dead * 0.045 * (0.4 + progress);
        }
    }

    // MUTATION 4: threshold sweep on the near-perfect band — extend the
    // heavily rewarded residual band from 1-4 to 1-6 with a graded decay,
    // so placements leaving residual 5-6 (still easily fillable by small
    // items) get partial credit instead of falling into the penalty band.
    if post_residual >= 5 && post_residual <= 6 {
        score -= 115.0 - (post_residual as f64 - 4.0) * 34.0;
    }

    // MUTATION 5: mean-residual harmonic targeting — refine the drift term
    // with a quadratic component so residuals near the fleet mean are
    // strongly preferred, improving cross-bin combinability of leftovers.
    if post_residual > 0 {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * drift * 0.006;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 110.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 55.0;
        } else if post_residual < 18 {
            score += 22.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.7;
            if slack <= 3 {
                score -= (4.0 - slack) * 7.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.0;
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 170.0;
    }

    // Tight-fit ratio: reward placements consuming a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 16.0;
    }

    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
