    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // Residual-variance squeeze continuation — doubly stranded fragments.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // Near-exact chain — reward when the current item leaves a post
    // residual that the next item can consume almost exactly (slack <= 2).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // Mid-band residual consolidation — residuals in the 26-40 band are
    // the most common source of waste; when multiple bins fit, prefer the one
    // that escapes this band entirely (post residual 0 or >= 41).
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // New-bin threshold refinement — opening a fresh bin is only worth
    // it when the best alternative would strand a large fraction of residual.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // NEW: waste-budget lookahead — when the next item cannot fit any post
    // residual of the alternatives, quantify the dead space the current
    // placement would strand relative to the theoretical item budget and
    // penalize proportionally, sharpening dead-space diagnosis.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && bin_residual < bin_capacity {
        let dead_fraction = post_residual as f64 / bin_residual as f64;
        score += dead_fraction * 26.0 * (0.35 + progress);
    }

    // NEW: exact-closure arbitration — when the current placement closes the
    // bin exactly and the next item would otherwise need a fresh bin, deepen
    // the reward; closing a bin that hosts the next item's demand is worth
    // more than the marginal residual elsewhere.
    if post_residual == 0 && next_item_size > 0 && fitting_bins_count <= 2 {
        score -= 40.0 * (0.5 + progress);
    }

    // NEW: residual ceiling harmonization — prefer placements whose post
    // residual stays above the next item when the bin is nearly full, so the
    // remaining gap remains serviceable rather than a hair-thin sliver.
    if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
        score += (5.0 - post_residual as f64) * 4.5;
    }

    // NEW: large-residual preservation under scarcity — when few bins fit and
    // the item is small, avoid burning a big residual on a tiny item unless
    // the post residual remains broadly reusable (>= next item or >= 50).
    if item_size <= 20 && fitting_bins_count <= 3 && bin_residual < bin_capacity
        && post_residual > 0 && post_residual < 50
        && (next_item_size == 0 || post_residual < next_item_size) {
        score += 12.0 * (1.2 - progress);
    }

    // NEW: fresh-bin waste bound — a new bin opened for a small item wastes
    // capacity proportional to (capacity - item); discourage unless the item
    // is large enough that the leftover stays valuable.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let leftover = (bin_capacity - item_size) as f64;
        if item_size < 40 {
            score += (40.0 - item_size as f64) * 1.4;
        } else if leftover >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1250.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 115.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 60.0;
        } else if post_residual < 18 {
            score += 24.0;
        } else if post_residual < 35 {
            score += 7.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 85.0 - slack * 0.7;
            if slack <= 3 {
                score -= (4.0 - slack) * 7.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.0;
            if post_residual < 10 {
                score += 32.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 175.0;
    }

    // Tight-fit ratio: reward placements consuming a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 16.0;
    }

    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.9;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate: attractive only when no alternative exists.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -38.0
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -26.0
        } else {
            105.0 + open_bins_count as f64 * 2.2
        };
        score += penalty;
    }

    // Residual balancing: prefer bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else if post_residual as f64 > mean_residual + 18.0 {
        score += (post_residual as f64 - mean_residual - 18.0) * 0.4;
    }

    // Progress-driven tightness.
    let tightness = if progress < 0.15 { 0.18 } else { 0.11 * (1.0 + progress) };
    score -= (bin_capacity - post_residual) as f64 * tightness;

    // Chain potential: post residual can host next item with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        if chain_slack > 0 && chain_slack <= 12 {
            score -= 15.0;
        }
    }

    // Anti-fragmentation: residual equal to item size stays reusable.
    if post_residual > 0 && post_residual == item_size {
        score -= 20.0;
    }

    // Awkward-residual trap: 20-45 band unusable by next item.
    if post_residual >= 20 && post_residual <= 45 && next_item_size > post_residual {
        score += 12.0;
    }

    // Late-stream consolidation: fill existing bins almost completely.
    if progress > 0.7 && post_residual > 0 && post_residual < 25 {
        score -= 9.0 * progress;
    }

    // Exact-pair anticipation: two identical items exactly fill the bin.
    if next_item_size > 0 && next_item_size == item_size && item_size * 2 == bin_residual {
        score -= 45.0;
    }

    // Mid-stream selection sharpening: many fitting bins -> prefer emptiest.
    if fitting_bins_count > 2 && bin_residual < bin_capacity {
        score += (bin_residual as f64) * 0.05;
    }

    // Reusable-residual harmony — post residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 24.0;
    }

    // Small-item sink — tiny items go into the smallest usable gap.
    if item_size <= 10 && post_residual > 0 && post_residual < 30 {
        score -= 16.0;
