        score += 30.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If no tight fit is available elsewhere, new bin becomes competitive:
        if fit_ratio < 0.5 && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild preference to fill bins with larger residual when many bins are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // Global state: penalize bins far from mean residual (fragmentation control).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
