pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (small post_residual) strongly -> convex penalty.
    // Late: residuals matter less; flatten the coupling.
    let t = progress;
    let poly = 1.0 - 1.6 * t + 0.8 * t * t; // smooth decreasing weight, stays positive
    score = score * (0.4 + 1.2 * poly);

    // Squared dead-space penalty, modulated by progress: punish waste more early.
    let dead = pr / cap;
    score += (dead * dead) * 40.0 * (1.0 - t);

    // Reward near-perfect fills (post_residual tiny) with a smooth bonus.
    let fill = 1.0 - dead;
    score -= (fill * fill * fill) * 12.0;

    // Last-chance bin: strong reward, decaying with progress.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - 0.5 * t);
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack * slack);
    }

    // Penalize bins whose residual deviates from the mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Slight preference for using existing bins over opening new ones as bins accumulate.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
}

