    if post_residual >= 1 && post_residual <= 6 && fitting_bins_count > 1 {
        score -= 10.0 + 6.0 * progress;
    }

    // NEW: exact-sum closure of the whole bin by current item alone is
    // already covered; instead reward item_size == bin_residual exactly.
    if item_size == bin_residual {
        score -= 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
