    // by the placement. A placement that cuts the residual to less than half
    // its size is a compaction step; encourage it proportionally.
    if bin_residual > item_size && bin_residual < bin_capacity {
        let half = bin_residual / 2;
        if post_residual <= half {
            let depth = if post_residual == 0 { 2.0 }
                else if post_residual <= half / 2 { 1.5 } else { 1.0 };
