    // gradient that tightens as the stream progresses.
    if next_item_size >= 20 && next_item_size <= 60 && fitting_bins_count >= 2
        && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 6.0 * (0.5 + progress);
        } else if post_residual > 0 {
            score += 4.0 * (0.5 + progress);
        }
    }

    score
}

