    // even and <= 100 can be closed by two equal halves, a strong signal
    // that the space is recoverable rather than stranded.
    if post_residual > 12 && post_residual <= 100 && post_residual % 2 == 0
        && next_item_size > 0 && next_item_size > post_residual {
        score -= 8.0 * (0.5 + progress);
    }

    // NEW: late-stream best-fit escalation — near the end, the marginal cost
    // of any leftover residual approaches one full bin; tighten the waste
    // coefficient beyond the parent's 0.45 slope with a superlinear push so
    // the last ~8% of items pack into existing bins almost exhaustively.
    if progress > 0.92 && post_residual > 0 {
        let r = post_residual as f64;
        score += r * r * 0.012;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with mild non-linear penalty
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate slack; later, punish leftover space more aggressively.
    let poly = 1.0 + 2.0 * progress * progress + 1.5 * progress * (1.0 - progress);
    score += 30.0 * norm_pr * norm_pr * poly;

    // Lookahead: reward bins whose post_residual can host the next item (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * snug * (0.5 + progress);
        } else {
            // post_residual too small for next item: penalize dead space
            score += 8.0 * norm_pr * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., unusually full bin) is good; reward it smoothly.
    let dev = (mean_residual - pr) / cap;
    score -= 6.0 * dev * dev.signum() * (0.3 + 0.7 * progress) * dev.abs().min(1.0);

    // Many open bins: encourage consolidation (prefer bins, discourage waste)
    let open_pressure = (open_bins_count as f64).ln_1p();
    score += 4.0 * norm_pr * open_pressure;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

