            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size are
    // prime dead space; penalize proportionally to how unreachable they are.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // Doubly stranded fragments — post residual too small for next item AND
    // below mean residual is near-certain waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // Near-exact chain — next item consumes post residual almost exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // Mid-band residual consolidation — escape the wasteful 26-40 band.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // GEN 39 MUTATION: fine-grained fit + lookahead synthesis — combine
    // high fit quality with a chainable post residual; the compounding of
    // both signals identifies placements that leave no dead space while
    // preserving the exact-closure opportunity for the next item.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        let slack = post_residual - next_item_size;
        if fq > 0.85 && slack <= 4 {
            score -= (fq - 0.85) * 120.0 + (4 - slack) as f64 * 6.0;
        }
    }

    // GEN 39 MUTATION: off-by-small fragmentation trap — post residual just
    // below the next item is the worst dead space; escalate the penalty
    // sharply for gaps of 1-6 and couple with fitting scarcity.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 6 {
            score += (6.0 - gap) * 5.0 * (1.0 + progress)
                + if fitting_bins_count <= 2 { 10.0 } else { 0.0 };
        }
    }

    // GEN 39 MUTATION: residual-variance squeeze — when many bins fit,
    // steer selection toward post residuals near zero deviation from the
    // fleet mean, reducing residual dispersion across bins.
    if fitting_bins_count > 2 && post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // GEN 39 MUTATION: exact multiplicity chain — post residual being a
    // small multiple of the next item size enables a clean multi-item
    // closure sequence; reward the exact case strongly.
    if next_item_size > 2 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let r = post_residual % next_item_size;
        if r == 0 && q <= 4 {
            score -= 16.0;
        } else if r <= 2 {
            score -= 8.0;
        }
    }

    // GEN 39 MUTATION: new-bin acceptance tuned to item size and lookahead —
    // large items with a chainable follow-up may open bins early; small
    // items must reuse existing space, penalized progressively.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_after = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_after && progress < 0.5 {
            score -= 16.0 * (1.0 - progress);
        } else if item_size >= 70 {
            score -= 4.0;
        } else {
            score += (70 - item_size) as f64 * 0.7 * (0.5 + progress);
        }
    }

    // GEN 39 MUTATION: endgame exact-closure race — near the end, the
    // smallest achievable post residual dominates all other signals.
    if progress > 0.8 && post_residual > 0 {
        score += (post_residual as f64) * 0.55 * (progress - 0.8) * 5.0;
        if post_residual <= 5 {
            score -= 18.0 * (progress - 0.8) * 5.0;
        }
    }

    // GEN 39 MUTATION: scarcity protection — when only one or two bins can
    // host the next item, protect bins that keep that chain possibility.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size
        && bin_residual < bin_capacity {
        score -= 9.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect harmony, strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space classes
    // Class A: tiny residual (<=5) — nearly perfect, reward heavily
    if post_residual > 0 && post_residual <= 5 {
        score -= 60.0;
    }
    // Class B: small residual (6..15) — still quite usable
    else if post_residual <= 15 {
        score -= 25.0;
    }
    // Class C: mid residual (16..40) — moderate
    else if post_residual <= 40 {
        score -= 8.0;
    }
    // Class D: large residual (>40) — wasteful split
    else {
        score += 20.0;
    }

    // Modulo-10 harmonic classes: residuals that align with typical item sizes
    // (items often multiples of 5/10) are more reusable.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 10.0;
    } else if rem10 == 5 {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 15.0; // next item still fits
        } else {
            // next item won't fit here; penalize less if residual is tiny anyway
            if post_residual < next_item_size / 2 {
                score += 5.0;
            } else {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps existing bins preferred
        score += 30.0;
        // Open new bin if mean residual is small (existing bins nearly full)
        score -= (mean_residual / cap) * 45.0;
        // Early stream: slightly more willing to open bins
        score -= (1.0 - progress) * 10.0;
        // If many fitting bins exist, opening new bin is wasteful
        score += fitting_bins_count as f64 * 15.0;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    // Coupling with mean residual: prefer bins below mean residual (fill emptier-of-space bins first is bad;
    // actually fill bins with LESS residual than mean to balance toward fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
