    // final waste for this bin; apply a smooth, escalating floor that grows
    // quadratically for residuals above the commonly-fillable 12-unit band,
    // unless the next item can chain into it (keeping the lookahead intact).
    if post_residual > 0 {
        let chainable = next_item_size > 0 && post_residual >= next_item_size;
        let r = post_residual as f64;
        if !chainable && r > 12.0 {
            score += (r - 12.0) * (r - 12.0) * 0.045 * (0.4 + progress);
        }
    }

    // NEW: exact-closure ladder — reward placements whose post residual
    // equals a plausible sum of two small items (5..=30 each), a strong
    // signal the bin can be closed by a future pair; sharpen mid-stream.
    if post_residual > 0 && progress > 0.25 {
