            score -= 10.0 * (0.5 + progress);
        }
    }

    // NEW: fragmentation-vs-consolidation tradeoff — when many bins are open
    // and this bin's post residual would be small-but-nonzero, prefer keeping
    // larger residuals in circulation instead of shaving bins to crumbs.
    if open_bins_count > 6 && post_residual > 0 && post_residual < 15
        && next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are "dead space" -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual small but usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space coupling with lookahead: if the next item could have used
    // the residual we are about to waste, penalize more.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // If next item fits exactly into the post residual, reward keeping it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing existing
    // bins over opening new ones (new-bin candidate has max residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates from mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: make empty-bin option costly unless item is huge
    // relative to all residuals (handled implicitly by fitting pressure).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    }

    score
}

