        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // MUTATION: endgame new-bin suppression — never open fresh bins in the
    // final stretch when any existing bin fits.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.9 {
        score += 120.0;
    }

    score
}

