    // replace flat residual term with a convex penalty that grows faster
    // for mid-size stranded gaps (the diagnosed weakness), while keeping
    // large residuals cheap since they stay combinable.
    if post_residual > 0 {
        let r = post_residual as f64;
        let convex = if r <= 20.0 {
            r * 0.30
        } else if r <= 45.0 {
