    }

    // MUTATION: near-closure band sharpening — residuals 1-6 late in the
    // stream are effectively closed; deepen the reward with progress.
    if post_residual >= 1 && post_residual <= 6 && progress > 0.5 {
        score -= 20.0 * progress;
    }

    // MUTATION: combinability-aware large-residual preference — when few
    // bins are open, a large post residual is an asset, not waste; reward
    // keeping it above the mean so future mid-size items combine well.
    if open_bins_count <= 4 && post_residual > 0
        && post_residual as f64 >= mean_residual && next_item_size > 0
        && post_residual >= next_item_size {
        score -= 7.0;
    }

    // MUTATION: new-bin final gate — a fresh bin must beat the best open
    // option by a clear margin; scale its penalty with the tightness of the
    // best alternative fit so marginal new-bin openings are suppressed.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let tightness_alt = item_size as f64 / mean_residual.max(1.0);
        score += tightness_alt * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is already low score).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    }

    // 2-step lookahead: reward when the next item can fit into the post residual,
    // giving an extra bonus if it exactly fills it (two-item perfect packing).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - post_residual as f64).abs() < 1.0 {
            score -= 500.0; // next item exactly fills remainder
        } else if next_item_size <= post_residual {
            score -= 150.0 * (1.0 - (post_residual as f64 - ni) / cap);
        } else {
            // dead space that the next item cannot use: penalize proportionally
            score += 0.5 * (post_residual as f64 - ni);
        }
    }

    // Compare post residual against mean residual: leaving this bin far above
    // the mean wastes space elsewhere; far below mean is good consolidation.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the item is large relative to residual (poor fit case handled above).
    if bin_residual == bin_capacity {
        score += 80.0 + 0.2 * mean_residual;
    }

    // Slight preference for filling older/more-filled bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    score
}

