    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Penalize creating dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead gap for the next item: penalize proportionally to the gap size,
            // but only if the gap is small enough to be truly "dead" (unusable).
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 40.0 * (1.0 - gap / 10.0);
            }
            // Bonus if this bin can still take the next item afterwards.
        } else {
            score -= 8.0; // leaves room for the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. A fresh bin has post_residual = C - item,
    // which is usually large, so add a fixed opening penalty to discourage
    // proliferation of bins, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        let open_penalty = 25.0 + 3.0 * open_bins_count as f64;
        score += open_penalty;
        // But if the item is huge, a fresh bin wastes little; soften the penalty.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill_ratio;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference for filling bins that are already relatively full
    // (keeps many low-residual bins, leaves flexible high-residual bins open).
    let fullness = 1.0 - (post_residual as f64) / bin_capacity as f64;
