pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by 10 are
    // "harmonic" (likely to match future item sizes in a 10-granularity world),
    // odd / prime residues are less reusable.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 6.0; // harmonic residue, highly reusable
        } else if r % 5 == 0 {
            score -= 2.0;
        } else if r % 2 == 0 {
            score += 1.0;
        } else {
            score += 3.0; // odd residue, poor reuse odds
        }
    }

    // Dead-space penalty: residual below the minimum item size is waste.
    if r > 0 && r < 10 {
        score += 25.0 * (10 - r) as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if it fits at all, mild reward; if it wastes capacity, penalize.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0; // perfect harmonic pair
        } else if next_item_size < r {
            let slack = r - next_item_size;
            score -= 10.0;
            if slack < 10 {
                score += 12.0 * (10 - slack) as f64; // would create fresh dead space
            }
        } else {
            score += 5.0; // next item cannot use this residual
        }
    }

    // Integer-division thresholds on post residual classes.
    let class = r / 20; // 0..5
    score += class as f64 * 2.0; // prefer leaving small (but usable) residuals

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin is expensive; only attractive when the
    // item is large enough that no open bin would leave a good residue.
    if bin_residual == bin_capacity {
        score += 30.0;
        // A big item in a fresh bin leaves little waste, mild discount.
        score -= (item_size as f64) * 0.25;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Many open bins: discourage spreading.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Prefer tighter bins: reward when bin_residual is close to item_size.
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - tightness) * 5.0;
        // Prefer bins whose residual is below the mean (dense bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

