    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // GEN 41 MUTATION: fine-grained fit + lookahead synergy — combine the
    // fit-quality of the current placement with the ability of the post
    // residual to host the next item; reward the joint condition strongest
    // when the leftover after the next item is small (tight chain closure).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        let r2 = post_residual - next_item_size;
        if fq > 0.8 {
            score -= (fq - 0.8) * 60.0 * (0.5 + progress);
        }
        if r2 <= 4 {
            score -= 10.0 + 6.0 * (1.0 - progress);
        }
    }

    // GEN 41 MUTATION: dead-space ratio sharpening — post residual that is a
    // small fraction of the next item is nearly-certain waste; penalize
    // proportionally to the unusable fraction, scaled by open-bin pressure.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.5 {
            score += (0.5 - unusable) * 30.0 * (0.6 + progress)
                + open_bins_count as f64 * 0.4;
        }
    }

    // GEN 41 MUTATION: new-bin acceptance with lookahead trade-off — opening a
    // fresh bin is acceptable only when the item is large and the next item
    // would strand no existing residual; otherwise penalize with a
    // progress-scaled barrier.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 22.0 + 30.0 * progress;
        }
    }

    // GEN 41 MUTATION: multi-item closure chain — post residual divisible by
    // the next item size suggests repeated identical placements can close
    // the bin exactly; reward small quotients (2-4 repeats).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let r = post_residual % next_item_size;
        if r == 0 && q >= 2 && q <= 4 {
            score -= 12.0 * (0.6 + progress);
        }
    }

    // GEN 41 MUTATION: residual-variance squeeze — when many bins fit, prefer
    // placements whose post residual stays close to the fleet mean residual,
    // keeping future combinability high across the whole fleet.
    if fitting_bins_count > 2 && post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.10;
    }

    // GEN 41 MUTATION: fragmentation trap — post residual just below next item
    // (off-by-small gap) is the worst kind of dead space; penalize harder
    // when few alternatives exist to absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8 {
            score += (8.0 - gap) * 3.5 * (1.0 + progress)
                + if fitting_bins_count <= 2 { 8.0 } else { 0.0 };
        }
    }

    // GEN 41 MUTATION: late-stream exact-closure race — near the end, the
    // smallest achievable post residual dominates; escalate sharply.
    if progress > 0.8 && post_residual > 0 && post_residual <= 5 {
        score -= 15.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    // Assume smallest item ~ (bin_capacity / 10). Gap below that threshold is wasted.
    let min_item = (bin_capacity as f64 * 0.1).max(1.0);
    if (post_residual as f64) < min_item && post_residual > 0 {
        // Quadratic penalty scaled by how deep into dead-zone the gap falls.
        let dead_depth = (min_item - post_residual as f64) / min_item;
        score += 25.0 + 40.0 * dead_depth * dead_depth;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if the leftover gap could have fit the next item but doesn't exactly match:
    // wasted potential for chain packing.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual != next_item_size {
        score += 4.0;
    }

    // Last-chance pressure: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, tighten packing (prefer tight fits,
    // discourage opening new bins); when few bins are open, be more permissive.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Mean-residual coupling: if this bin's residual is far below the mean (already tight),
    // finishing it off is good; if it's much looser than mean, penalize leaving mid-range gaps.
    let residual_gap = bin_residual as f64 - mean_residual;
    if residual_gap < 0.0 {
        score += residual_gap * 0.15; // tighter-than-average bin favored (negative gap lowers score)
    }

    // Late in the stream, prefer closing bins out (avoid stranding residual capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // New-bin candidate: make an empty bin moderately attractive only when the current
    // item is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item || fitting_bins_count == 0 {
            score -= 8.0;
        } else {
            score += 12.0; // discourage opening new bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1250.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 115.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 60.0;
        } else if post_residual < 18 {
            score += 24.0;
        } else if post_residual < 35 {
            score += 7.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 85.0 - slack * 0.7;
            if slack <= 3 {
                score -= (4.0 - slack) * 7.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.0;
            if post_residual < 10 {
                score += 32.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 175.0;
    }

    // Tight-fit ratio: reward placements consuming a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 16.0;
    }

    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.9;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate: attractive only when no alternative exists.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -38.0
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -26.0
        } else {
            105.0 + open_bins_count as f64 * 2.2
        };
        score += penalty;
