        let leftover_frac = post_residual as f64 / bin_residual as f64;
        if item_size * 4 <= bin_residual && leftover_frac > 0.8 {
            score += 12.0 * (0.4 + progress);
        }
    }

    // NEW: new-bin gating refinement — a fresh bin should only win when the
    // best existing alternative leaves more dead space than the fresh bin's
    // guaranteed reusability; sharpen the boundary with a graded penalty.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let alt_waste = (post_residual as f64).max(1.0);
