    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that cannot fit the next item (wasted capacity).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 {
        // Reward bins that can also host the lookahead item.
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Coupling with global state: prefer bins below mean residual when many bins open.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.05;

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let base = 30.0 + item_size as f64 * 0.6;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a new bin keeps room for the similar/larger next item.
            score = base - 10.0;
        } else {
            score = base;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

