    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space variance squeeze — reward modular residue class alignment.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling — protect bins that can chain the next item.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-decay gradient — reward consuming >70% of the residual.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // Stranded-gap arithmetic guard — 31-59 band unreachable by next item.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // Two-item sum closure — post residual closable by next item plus small.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // New-bin parity refinement — opening fresh bins is better early.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // Doubly stranded fragments — too small for next item AND below mean.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // Near-exact chain — next item consumes post residual almost exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // Mid-band residual consolidation — escape the wasteful 26-40 band.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // New-bin threshold refinement — compare against best alternative dead space.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // GEN 42 MUTATION: fine-grained lookahead synergy — reward placements where
    // the fit quality is very high AND the post residual can chain the next
    // item, scaled by fitting scarcity (combines best-fit with lookahead).
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual >= item_size {
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        if fq > 0.9 {
            score -= (fq - 0.9) * 90.0 * (1.0 - progress * 0.3);
        }
        if fitting_bins_count > 3 {
            score -= 6.0;
        }
    }

    // GEN 42 MUTATION: off-by-small fragmentation trap — post residual just
    // below the next item is the worst dead space; escalate when few
    // alternatives exist to absorb the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8 {
            score += (8.0 - gap) * 3.5 * (1.0 + progress);
        }
        if fitting_bins_count <= 2 {
            score += 16.0;
        }
    }

    // GEN 42 MUTATION: scarce-alternative tightening — protect bins that keep
    // the next item's placement possibility alive.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }

    // GEN 42 MUTATION: late-stream small-residual closure race — near the end,
    // the globally smallest achievable post residual dominates selection.
    if progress > 0.8 && post_residual > 0 && post_residual <= 5 {
        score -= 15.0 * (progress - 0.8) * 5.0;
    }

    // GEN 42 MUTATION: clean multi-item closure chain — post residual divisible
    // by both the next item and 3 suggests exact multi-item packing.
    if next_item_size > 2 && post_residual > 0 && post_residual % next_item_size == 0
        && post_residual % 3 == 0 {
        score -= 6.0;
    }

    // GEN 42 MUTATION: unusable-fraction dead-space sharpening — post residual
    // that is a small fraction of the next item is nearly-certain waste;
    // penalize proportionally with open-bin pressure.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.5 {
            score += (0.5 - unusable) * 30.0 * (0.6 + progress)
                + open_bins_count as f64 * 0.4;
        }
    }

    // GEN 42 MUTATION: new-bin acceptance with lookahead trade-off — opening a
    // fresh bin only when the item is large and the next item would fit it too;
    // otherwise apply a progress-scaled barrier.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let next_fits_now = next_item_size > 0 && next_item_size <= item_size;
        if item_size >= 70 && next_fits_now {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 22.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base cost: leftover space, scaled non-linearly by stream progress.
    // Later in the stream, leftover space becomes more costly (less chance to fill it).
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear penalty on dead space: residuals near mid-range are worst.
    score += 8.0 * (x * (1.0 - x)) * (1.0 + progress);

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * tightness;

    // Interaction with mean residual: placing into a bin far from the mean
    // residual helps balance the pool; penalize placements that worsen spread.
    let spread = pr - mean_residual;
    score += 0.3 * spread.abs() * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (next_item_size as f64 / cap) * (1.0 + progress);
        } else {
            score += 2.0 * progress;
        }
    }

    // New-bin candidate: prefer it only when open bins have large residuals
    // and the item is big, otherwise penalize opening new bins mildly.
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / cap;
        let big_item = item_size as f64 / cap;
        score += 4.0 - 6.0 * open_pressure * big_item - 3.0 * progress * (1.0 - big_item);
    }

    // Slight preference for fuller bins as stream progresses.
    score -= 0.05 * (bin_residual as f64 - pr) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
