    // placements that strand more than half of the original residual while
    // the next item cannot use the leftover.
    if bin_residual > 0 && bin_residual < bin_capacity && post_residual > 0 {
        let stranded_frac = post_residual as f64 / bin_residual as f64;
        if next_item_size > 0 && post_residual < next_item_size {
            score += stranded_frac * 22.0 * (0.5 + progress);
        } else if stranded_frac <= 0.25 {
            score -= (0.25 - stranded_frac) * 30.0;
        }
    }

    // MUTATION: combinatorial closure potential — count how many plausible
    // small item sizes (multiples of 5 up to the post residual) could later
    // combine with the next item to close the bin; reward richer options.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        let options = (1..=r2.min(20)).filter(|&s| r2 % s == 0 || s >= r2 / 2).count();
        score -= options as f64 * 2.5 * (0.4 + progress);
    }

    // MUTATION: wasteful-fit veto — when the item barely fits a large
    // residual (consumes < 30%) and other bins fit the item, penalize this
    // placement so items route to bins where they compact better.
    if fitting_bins_count > 1 && bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed < 0.3 {
            score += (0.3 - consumed) * 40.0;
        }
    }

    // MUTATION: residual ladder harmonization — prefer post residuals that
    // remain reachable by a plausible future item in the 1-100 range given
    // typical stream granularity; residuals in the 46-55 "dead middle" band
    // are penalized unless the next item can use them.
    if post_residual >= 46 && post_residual <= 55
        && !(next_item_size > 0 && post_residual >= next_item_size) {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item
    // granularity (10) are reusable; small odd residues are dead space.
    let gran = 10u32;
    let res_mod = post_residual % gran;
    if res_mod == 0 {
        score -= 12.0; // perfectly aligned residual, highly reusable
    } else if res_mod <= 2 {
        score += 6.0; // nearly-dead sliver
    } else if res_mod >= gran - 2 {
        score -= 3.0; // close to next alignment class
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / gran; // 0..10
    match cls {
        0 => score += 25.0, // tiny residual: bin essentially exhausted (good if exact)
        1 => score -= 8.0,  // residual ~10-19: fits smallest items well
        2 => score -= 5.0,  // residual ~20-29
        3 => score -= 2.0,
        4..=6 => score -= 0.0,
        _ => score += 4.0,  // large leftover: wasteful placement
    }

    // Exact fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can land here too — reward proportional to class
            let ncls = (post_residual - next_item_size) / gran;
            score -= 6.0 + ncls as f64;
        } else {
            // next item won't fit here; penalize unless residual is tiny
            if post_residual > 0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mild penalty when many bins are open and this placement is loose
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Deviation from mean residual: prefer bins below-average residual
    // (tighter bins) when the fit is close
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 2.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers
    // a genuinely tight fit (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        let tight_threshold = 15.0;
        if post_residual as f64 > tight_threshold {
            score -= 5.0; // fresh bin keeps space flexible
        } else {
            score += 20.0; // discourage opening bins when a tight fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
