    // Lookahead-scarcity coupling for large next items.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-combinability index — reward post residuals expressible
    // as sums of two common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
        if combinable {
            score -= 7.0 * (0.5 + progress);
        }
    }

    // Slack-variance squeeze — when several bins fit, sharpen preference
    // toward the bin whose post residual best matches the mean residual.
    if fitting_bins_count > 2 && post_residual > 0 && bin_residual < bin_capacity {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.10 * progress;
    }

    // Triple-fill exact anticipation — current + next leaves a residual
    // equal to a plausible third item (half of next), enabling full closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // New-bin gating refinement — block fresh bins when a near-zero-slack
    // fit exists in an existing bin.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if item_size >= 90 {
            score += 40.0;
        }
    }

    // NEW: residual-decay gradient — reward consuming >70% of the residual,
    // with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // NEW: stranded-gap arithmetic guard — residuals in the 31-59 band that
    // the next item cannot use and that exceed twice the next item's size
    // are prime dead space; penalize proportionally to unreachability.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // NEW: two-item sum closure — post residual can be closed by next item
    // plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // NEW: new-bin parity refinement — when opening a fresh bin is the only
    // option, prefer it early (residual stays maximal) but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // NEW: residual-variance squeeze continuation — penalize doubly stranded
    // fragments (too small for next item AND below fleet mean residual).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // NEW: near-exact chain — reward when post residual can be consumed
    // almost exactly by the next item (slack <= 2), mid/late stream.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // NEW: mid-band residual consolidation — residuals in the 26-40 band are
    // the most common source of waste; when multiple bins fit, prefer the one
    // that escapes this band entirely (post residual 0 or >= 41).
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // NEW: new-bin threshold refinement — opening a fresh bin is only worth
    // it when the best alternative would strand a large fraction of residual.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // NEW: fused compaction — combine fine-grained residual fitting with
    // lookahead anticipation: reward placements where the current item is a
    // near-exact fit AND the post residual can host the next item, coupling
    // both signals into a single escalating bonus.
    if bin_residual < bin_capacity && post_residual > 0 && next_item_size > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        let hosts_next = post_residual >= next_item_size;
        if slack <= 8 && hosts_next {
            let tight = (8 - slack) as f64;
            score -= tight * 2.2 * (0.5 + progress);
        }
    }

    // NEW: lookahead pair-sum closure — post residual equals the sum of the
    // next item and a small plausible follow-up item (<= 15), enabling
    // three-way exact closure later in the stream.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 15 && progress > 0.3 {
            score -= 9.0 * (0.5 + progress);
        }
    }

    // NEW: dead-space ratio escalation — when the next item cannot use the
    // post residual and it exceeds twice the next item's size, apply a
    // quadratic penalty scaled by progress to push toward tighter fills.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded_frac = post_residual as f64 / next_item_size as f64;
        score += stranded_frac * stranded_frac * 10.0 * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

