        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // New-bin gating refinement — block new bins on near-exact fits.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size >= 90 {
        score += 40.0;
    }

    // MUTATION: residual-decay gradient — reward consuming >70% of the
    // residual, with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
