        }
    }

    // MUTATION: new-bin parity refinement — when opening a fresh bin is the
    // only option, prefer it early (residual stays maximal), not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // MUTATION: residual-variance squeeze — penalize residuals that are
    // simultaneously too small for the next item AND below the mean residual
    // (doubly stranded fragments).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // MUTATION: near-exact chain — reward when the current item leaves a post
