        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // MUTATION: mid-band residual consolidation — residuals in the 26-40 band
    // are the most common source of waste; when multiple bins fit, prefer the
    // one that escapes this band entirely (post residual 0 or >= 41).
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // MUTATION: new-bin threshold refinement — opening a fresh bin is only
    // worth it when the best alternative would strand a large fraction of
    // residual; scale the fresh-bin penalty by alternative dead space.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100 unknown,
    // but historically tiny gaps < 12 are near-useless) can fill are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }
    // Mid-range dead space (12..30) is mildly risky.
    if post_residual >= 12 && post_residual < 30 {
        score += 0.8 * (30.0 - post_residual as f64);
    }
    // Perfect or near-perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another gap: slight penalty proportional to the second gap.
        let second_gap = post_residual - next_item_size;
        if second_gap < 12 {
            score += 0.5 * (12.0 - second_gap as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // Many competing bins: prefer the tightest (already via post_residual), but add mild
    // pressure to close out bins when many are open.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins even more.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
        // Don't open a new bin when next item would fit the fresh bin too and bins are few.
        if next_item_size > 0 && open_bins_count < 3 {
            score += 15.0;
        }
    }

    score
}

