    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match gets a strong bonus; near matches get partial credit.
        score -= 40.0 * (-gap / 12.0).exp();
        // Penalize leaving residual too small for the next item (dead space risk)
        // unless it's tiny itself.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit, slight bonus for using an existing bin.
        score -= 5.0;
    }

    // Compare post_residual against the mean residual: leaving less than average
    // residual means this bin was well utilized.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect 2-step chain that no open bin offers.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 {
            let chain = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs();
            if chain == 0 {
                score -= 45.0; // fresh bin fits item + next item exactly
            }
        }
    }

    // Mild late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Prefer bins with tighter original residual among equals.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

