    // as sums of two common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
