    // common waste source; when alternatives exist, escape it entirely.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // MUTATION: doubly-stranded fragment guard — residual too small for next
    // item AND below fleet mean is dead space; penalize harder.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // MUTATION: near-exact chain — next item consumes post residual almost
    // exactly (slack 1-2), extending chain potential into a tighter band.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // MUTATION: stranded-gap arithmetic guard — 31-59 band unreachable by
    // next item and exceeding twice its size is prime dead space.
    if post_residual >= 31 && post_residual <= 59 && next_item_size > 0
        && next_item_size > post_residual && post_residual > next_item_size * 2 {
        score += 14.0 + 6.0 * progress;
    }

    // MUTATION: new-bin parity refinement — fresh bins preferable early,
    // wasteful late; scale by remaining stream.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    // MUTATION: new-bin threshold refinement — opening a fresh bin only worth
    // it when alternatives would strand a large fraction of residual.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary best-fit core: reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable dead space (post_residual in awkward zone).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 18.0 * chain;
    }
    // If next item would fit only if we keep more space, penalize consuming it all.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if mean_residual > 0.0 {
        let consolidation = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * consolidation;
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits);
    // late in stream, just fill bins and avoid opening new ones.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 8.0 * (1.0 - fit_ratio);
    score -= t * 12.0;

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += desperation + 5.0 * (1.0 - t);
        // If item is huge relative to capacity, new bin is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If open bins are fragmented (high mean residual spread), opening new bin is OK.
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Slight preference for fuller bins among equals.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

