    }

    // NEW: late-stream near-closure escalation — sharpen the reward for
    // leaving residuals of 1-8 as the stream nears its end, squeezing the
    // last bins tighter.
    if progress > 0.75 && post_residual >= 1 && post_residual <= 8 {
        score -= 18.0 * progress;
    }

    // NEW: big-item best-fit guard — large items should prefer the bin with
    // the smallest usable residual to avoid fragmenting fresh bins.
    if item_size > 70 && bin_residual < bin_capacity && post_residual > 0 {
        score += (bin_residual as f64) * 0.04;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space penalty grows superlinearly for unusable slivers (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward bins whose post residual lands on a "harmonic" size class:
    // multiples of 10, 20, 25, 50 are more likely reusable by future items.
    let harmonic = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 20 == 0) as f64 * 6.0
        + (post_residual % 25 == 0) as f64 * 5.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= harmonic;

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well it fits
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 20.0 * fill;
        } else {
            // next item cannot use this residual; penalize large leftovers slightly
            score += 0.15 * post;
        }
    }

    // Integer-division threshold on post_residual: bins with tiny leftovers are bad
    let div_class = post_residual / 10; // 0..=10
    score += match div_class {
        0 => 25.0,          // post_residual < 10: nearly dead
        1 => 5.0,           // 10..19: awkward
        2 => -3.0,          // 20..29: decent
        3..=4 => -6.0,      // 30..49: good
        _ => 0.0,
    };

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when the item is huge relative to capacity
    // or when open bins are all quite full (mean residual small).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // new bins are attractive for large items when few bins can fit
        score -= 10.0 * item_frac;
        score += 0.5 * mean_residual.max(0.0);
        // late in the stream, avoid proliferating bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Reward tight fits (small post residual relative to capacity)
        score -= (1.0 - frac) * 12.0;
    }

    // Mild penalty for placing into a bin far emptier than average (waste potential)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

