    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min item size = 1, but practically small gaps) are wasted.
    // Penalize gaps that are unusable for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Penalize tiny dead gaps that likely can never be filled.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward using bins whose residual was already small (consolidation).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure
        // and mean residual (if open bins still have room, don't open new).
        score += 15.0 + pressure + mean_residual.max(0.0) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // no open bin could ever take next item anyway
        }
    } else {
        // Existing bin: slight reward scaling with pressure to fill it.
        score -= pressure * 0.5;
    }

    // Lookahead synergy: if this placement leaves room exactly for next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    score
}

