        score += 20.0;
    }

    // Fitting-count scarcity bonus — keep scarce bins most reusable.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity && post_residual >= 25 {
        score -= 10.0;
    }

    // Endgame sweep — final stretch, any nonzero residual is nearly pure waste.
    if progress > 0.92 && post_residual > 0 {
        score += (post_residual as f64) * 0.45;
    }

    // Dead-space-ratio quadratic refinement fused with slack-sharpness gradient.
    if post_residual > 0 {
        let dr = post_residual as f64 / bin_capacity as f64;
        let hostable = next_item_size > 0 && post_residual >= next_item_size;
        let small_hostable = post_residual <= 12;
        if !hostable && !small_hostable {
            score += dr * dr * 60.0 * (0.4 + progress);
        }
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 / (1.0 + slack * 0.35)) * 20.0 * (0.5 + progress);
    }

    // Near-closure trap guard fused with residual-band reusability.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 6 {
        score += 25.0 + 20.0 * progress;
    }
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 7 == 0)
        && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Lookahead tight-fit coupling with scarcity amplification.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 18.0;
        }
    }

    // Dead-space variance squeeze — modular residue class alignment.
    if post_residual > 0 && post_residual < 60 {
        let class_align = (post_residual % 3 == 0) as f64;
        score -= class_align * 6.0 * (0.4 + progress);
        if post_residual % 3 == 1 && next_item_size > 0 && post_residual < next_item_size {
            score += 5.0 * (0.4 + progress);
        }
    }

    // Lookahead-scarcity coupling for large next items.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-combinability index — reward post residuals expressible
    // as sums of two common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
        if combinable {
            score -= 7.0 * (0.5 + progress);
        }
    }

    // Slack-variance squeeze — when several bins fit, sharpen preference
    // toward the bin whose post residual best matches the mean residual.
    if fitting_bins_count > 2 && post_residual > 0 && bin_residual < bin_capacity {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.10 * progress;
    }

    // Triple-fill exact anticipation — current + next leaves a residual
    // equal to a plausible third item (half of next), enabling full closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // New-bin gating refinement — when a fresh bin would be opened but
    // the item fits with near-zero slack in an existing bin, block new bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        if item_size >= 90 {
            score += 40.0;
        }
    }

    // MUTATION 1: residual-decay gradient — reward consuming >70% of residual
    // with an escalating bonus as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // MUTATION 2: two-item sum closure — post residual can be closed by next
    // item plus a small follow-up; reward when r2 lands in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // MUTATION 3: doubly stranded fragments — residual too small for next item
    // AND below mean residual is prime dead space.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // MUTATION 4: near-exact chain — next item consumes post residual almost
    // exactly (slack 1-2), extending chain potential into a tighter band.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // MUTATION 5: mid-band residual consolidation — 26-40 band is the most
    // common waste source; when multiple bins fit, escape this band entirely.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // MUTATION 6: new-bin threshold refinement — opening a fresh bin is only
    // worth it when the best alternative would strand a large residual fraction.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // MUTATION 7: new-bin parity refinement — prefer fresh bins early, not late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
