    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // GEN 45 MUTATION: fine-grained residual fitting fused with lookahead —
    // reward placements whose post residual is a small exact multiple of the
    // next item size (clean chain packing) AND whose fit quality is very high,
    // scaled by fitting scarcity so it fires when alternatives are limited.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        let fq = item_size as f64 / bin_residual.max(1) as f64;
        if rem == 0 && post_residual / next_item_size <= 4 {
            score -= 12.0 + 6.0 * fq;
        } else if rem <= 2 && fq > 0.8 {
            score -= 8.0 * (0.5 + progress);
