    // GEN 45 MUTATION: dead-space ratio sharpening — post residual that is a
    // small fraction of the next item is nearly-certain waste; penalize
    // proportionally to the unusable fraction and open-bin pressure.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let unusable = post_residual as f64 / next_item_size.max(1) as f64;
        if unusable < 0.5 {
            score += (0.5 - unusable) * 28.0 * (0.6 + progress)
                + open_bins_count as f64 * 0.35;
        }
    }

    // GEN 45 MUTATION: new-bin acceptance with lookahead trade-off — opening a
    // fresh bin is acceptable only when the item is large and the next item
    // would fit in the fresh residual; otherwise apply a progress-scaled
