    // exist, prefer the placement whose post residual deviates least from the
    // fleet mean residual, improving future cross-bin combinability.
    if fitting_bins_count > 2 && post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.12;
    }

    score
}

