        if next_item_size == post_residual {
            // Perfect chain fit: strongly reward
            score -= 50.0 + 30.0 * (1.0 - progress);
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to tightness
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * ratio;
        } else {
            // Next item won't fit here: penalize dead space creation
            let overflow = (next_item_size - post_residual) as f64;
            score += 8.0 * (overflow / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal final residual
        score += 5.0;
    }

    // Compare post_residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            // Tighter than average: reward
            score -= 10.0 * (1.0 - rel);
        } else {
            // Looser than average: penalize
            score += 6.0 * (rel - 1.0).min(3.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        // If many bins fit, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Slight preference for tighter fits overall
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
