        }
    }

    // Mid-band residual consolidation.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // New-bin threshold refinement based on alternative dead space.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // MUTATION: residual-combinability gradient — post residuals that can be
    // exactly decomposed into two plausible future items (both >= 5) are far
    // more likely to close later; reward such decomposable residuals and
    // penalize "prime-ish" residuals in the 37-53 band that admit no small
    // decomposition, scaled by stream position.
    if post_residual > 0 && post_residual < bin_capacity {
        let mut decomposable = false;
        let r = post_residual;
        let lo = if r >= 10 { 5u32 } else { 1 };
        let hi = r / 2;
        let mut a = lo;
        while a <= hi {
            if r - a >= a {
                decomposable = true;
                break;
            }
            a += 1;
        }
        if decomposable {
            score -= 8.0 * (0.4 + progress);
        } else if r >= 37 && r <= 53 {
            score += 12.0 * (0.4 + progress);
        }
    }

    // MUTATION: inter-bin residual pairing — when another open bin's mean
    // residual combined with this post residual could reach a full closure,
    // reward steering residuals toward such complementary sums (target the
    // capacity - mean_residual complement band).
    if post_residual > 0 && open_bins_count > 1 {
        let complement = bin_capacity as f64 - mean_residual;
        let dist = (post_residual as f64 - complement).abs();
        if dist < 15.0 {
            score -= (15.0 - dist) * 0.9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating dead space too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty unless residual was already small
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad waste.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 25.0 - waste_pressure * 0.4 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big-next-item: fresh bin may help
        }
    }

    // Global balance: prefer bins whose residual is close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild preference to fill bins in crowded state.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Time horizon: later in stream, be greedier (minimize residual now).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    score
}

