pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: reward tight fits via non-linear post-residual penalty
    let mut score = pr as f64;

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, penalize large residuals more strongly (avoid dead space)
    let progress_coupling = 40.0 * progress * norm_pr * norm_pr * cap;
    score += progress_coupling;

    // Smooth cubic term: tiny residuals are golden, huge residuals are wasteful
    let cubic = -60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    score += cubic;

    // Lookahead: if next item fits exactly in the post-residual, strongly favor
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let next_fit_bonus = -30.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress * 0.5);
        score += next_fit_bonus;
        // Penalize if post-residual too small for next item (dead-end risk)
        if next_item_size as f64 > pr {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Many open bins: mild preference to consolidate into fuller bins
    let fullness = 1.0 - norm_pr;
    score -= 8.0 * fullness * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Mean residual context: prefer bins below mean residual (fuller than average)
    score += 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: make it slightly unattractive unless residual truly unusable
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

