    // Lookahead-scarcity coupling for large next items.
    if next_item_size > 50 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += (bin_residual as f64) * 0.08;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 35.0;
    }

    // Residual-combinability index — reward post residuals expressible
    // as sums of two common small sizes (highly fillable later).
    if post_residual > 0 && post_residual <= 100 {
        let r = post_residual;
        let combinable = (r <= 20)
            || (r % 10 == 0)
            || (r >= 25 && r <= 55 && r % 5 == 0)
            || (r >= 30 && r % 15 == 0);
        if combinable {
            score -= 7.0 * (0.5 + progress);
        }
    }

    // Slack-variance squeeze — when several bins fit, sharpen preference
    // toward the bin whose post residual best matches the mean residual.
    if fitting_bins_count > 2 && post_residual > 0 && bin_residual < bin_capacity {
        let drift = (post_residual as f64 - mean_residual).abs();
        score += drift * 0.10 * progress;
    }

    // Triple-fill exact anticipation — current + next leaves a residual
    // equal to a plausible third item (half or third of next).
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 * 2 == next_item_size || r2 * 3 == next_item_size {
            score -= 16.0;
        }
    }

    // New-bin gating refinement — block new bins when a near-zero-slack fit exists.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size >= 90 {
        score += 40.0;
    }

    // MUTATION: residual-decay gradient — reward consuming >70% of residual,
    // escalating as the fraction approaches 1 (borrowed from best heuristic).
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 55.0 * (0.5 + progress);
        }
    }

    // MUTATION: two-item sum closure — post residual closeable by next item
    // plus a small follow-up in the common 1-20 band.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 20 && item_size >= r2 {
            score -= 14.0 * (0.6 + progress);
        }
    }

    // MUTATION: mid-band residual consolidation — escape the wasteful 26-40 band.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // MUTATION: doubly stranded fragments — residual too small for next item
    // AND below the fleet mean residual is prime dead space.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && (post_residual as f64) < mean_residual {
        score += 9.0 * (0.5 + progress);
    }

    // MUTATION: near-exact chain — next item consumes post residual with
    // slack <= 2, mid-to-late stream.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack >= 1 && slack <= 2 && progress > 0.4 {
            score -= 12.0 * (0.5 + progress);
        }
    }

    // MUTATION: new-bin threshold refinement — scale fresh-bin penalty by
    // how much dead space the best alternative would leave.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // MUTATION: new-bin parity refinement — prefer fresh bins early when
    // no alternative exists, but not wastefully late.
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        score -= 22.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are
    // "perfect fits" for common item classes (multiples of 10, 20, 25, 50).
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect packing
    } else if post % 50 == 0 && post > 0 {
        score -= 25.0;
    } else if post % 25 == 0 {
        score -= 18.0;
    } else if post % 20 == 0 {
        score -= 14.0;
    } else if post % 10 == 0 {
        score -= 10.0;
    } else if post <= 9 {
        score += 30.0; // dead space below min item size
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if post >= next_item_size {
            score -= 8.0;
            // harmonic class match between next item and residual
            if post % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; slight penalty scaled by leftover class
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // best-fit style: tighter fit preferred among many candidates
        score += (bin_residual - item_size) as f64 * 0.15;
    }

    // New-bin candidate: only attractive when current bins are fragmented
    // or the item would leave bad residuals everywhere.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // base cost of opening a bin
        score += 40.0;
        // if open bins are mostly full, opening fresh is fine
        score -= fragmentation * 55.0;
        // early in stream, prefer consolidating; late, allow spreading
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // avoid opening a bin for tiny items
        if item_size < 20 {
            score += 25.0;
        }
    }

    // Mean residual coupling: penalize bins far from mean when mean is small
    // (keeps packing balanced), reward deviation when mean is large.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual < cap * 0.3 {
        score += dev * 0.05;
    } else {
        score -= dev * 0.05;
    }

    // Modulo threshold on item class: large items (>= 51) prefer tightest fit
    if item_size >= 51 {
        score += (bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: dominant reward.
    if post_residual == 0 {
        score -= 1250.0;
    }

    // Near-perfect fill: reward residual 1-4 as nearly-closed bins.
    if post_residual >= 1 && post_residual <= 4 {
        score -= 110.0;
    }

    // Dead-space avoidance: penalize small unusable gaps harder as residual shrinks.
    if post_residual > 0 {
        if post_residual < 8 {
            score += 55.0;
        } else if post_residual < 18 {
            score += 22.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    }

    // Strong 2-step lookahead with slack sharpening.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack * 0.65;
            if slack <= 3.0 {
                score -= (4.0 - slack) * 6.5;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.95;
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Exact two-item pairing closes the bin: reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 165.0;
    }

    // Tight-fit ratio: reward placements consuming a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= fill_ratio * 15.0;
    }

    // Residual-decay gradient: reward consuming >70% of the residual,
    // escalating as the fraction approaches 1.
    if bin_residual > 0 && bin_residual < bin_capacity {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed > 0.7 {
            score -= (consumed - 0.7) * 50.0 * (0.5 + progress);
        }
    }

    // Waste-fraction coupling: penalize residuals no plausible item can use.
    if post_residual > 100 {
        score += (post_residual as f64 - 100.0) * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.85;

    // Last-chance bonus: only fitting bin strongly preferred over a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 52.0;
    }

    // New-bin candidate: attractive only when no alternative exists;
    // late in stream, strongly discourage fresh bins.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -36.0 * (1.0 - progress * 0.5)
        } else if next_item_size > 0 && post_residual >= next_item_size {
            -25.0
        } else {
            100.0 + open_bins_count as f64 * 2.2 + 55.0 * progress
        };
        score += penalty;
    }

    // Residual balancing: prefer bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else if post_residual as f64 > mean_residual + 18.0 {
        score += (post_residual as f64 - mean_residual - 18.0) * 0.38;
    }

    // Progress-driven tightness.
    let tightness = if progress < 0.15 { 0.17 } else { 0.11 * (1.0 + progress) };
    score -= (bin_capacity - post_residual) as f64 * tightness;

    // Chain potential: post residual can host next item with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        if chain_slack > 0 && chain_slack <= 12 {
            score -= 14.0;
        }
    }

    // Anti-fragmentation: residual equal to item size stays reusable.
    if post_residual > 0 && post_residual == item_size {
        score -= 20.0;
    }

    // Awkward-residual trap: 20-45 band unusable by next item.
    if post_residual >= 20 && post_residual <= 45 && next_item_size > post_residual {
        score += 12.0;
    }

    // Late-stream consolidation: fill existing bins almost completely.
    if progress > 0.7 && post_residual > 0 && post_residual < 25 {
        score -= 9.0 * progress;
    }

    // Exact-pair anticipation: two identical items exactly fill the bin.
    if next_item_size > 0 && next_item_size == item_size && item_size * 2 == bin_residual {
        score -= 42.0;
    }

    // Mid-stream selection sharpening: many fitting bins -> prefer emptiest.
    if fitting_bins_count > 2 && bin_residual < bin_capacity {
        score += (bin_residual as f64) * 0.05;
    }

    // Reusable-residual harmony — post residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 24.0;
    }

    // Small-item sink — tiny items go into the smallest usable gap.
    if item_size <= 10 && post_residual > 0 && post_residual < 30 {
        score -= 15.0;
    }

    // Three-step viability — post residual hosts next item leaving a small residual.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= 1 && r2 <= 12 && next_item_size >= r2 {
            score -= 10.0;
        }
    }

    // Avoid leaving residuals in the 61-99 band when next item cannot use them.
    if post_residual >= 61 && post_residual <= 99 && next_item_size > post_residual {
        score += (post_residual as f64 - 60.0) * 0.35;
    }

    // Pair-sum anticipation — next item plus current exactly fills residual.
    if next_item_size > 0 && next_item_size + item_size == post_residual {
        score -= 18.0;
    }

    // Many-fitting-bins tightness — best-fit sharpening when alternatives abound.
    if fitting_bins_count > 3 && bin_residual < bin_capacity {
        score -= (bin_capacity - post_residual) as f64 * 0.03;
    }

    // Late-stream zero-waste push — closing bins matters more near the end.
    if progress > 0.85 && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Residual-halving chain — a second identical item could close the bin.
    if post_residual > 0 && post_residual * 2 == bin_residual {
        score -= 22.0;
    }

    // Capacity-scaled waste pressure — tighter fills mid/late stream.
    if post_residual > 0 {
        score += (post_residual as f64) * 0.08 * progress;
    }

    // Exact post-residual reusability — residual in common small-item band.
    if post_residual > 0 && post_residual <= 12 && progress > 0.35 {
        score -= 16.0;
    }

    // Dead-space ratio penalty weighted by stranded capacity fraction.
    if post_residual > 0 {
        let stranded = post_residual as f64 / bin_capacity as f64;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        let reusable_band = post_residual <= 12 || post_residual % 5 == 0;
        if !usable_by_next && !reusable_band {
            score += stranded * 46.0 * (0.6 + progress);
        }
    }

    // Fit-margin sharpening — near-exact fits minimize residual variance.
    if post_residual > 0 {
        let slack = bin_residual.saturating_sub(item_size);
        if slack <= 5 {
            score -= (6.0 - slack as f64) * 6.0;
        }
    }

    // Next-item stranding guard — prefer alternatives that can host next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && fitting_bins_count > 1 && bin_residual < bin_capacity {
        score += 14.0;
    }

    // Stranding-risk coupling — waste scaled by progress.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.9 * (0.4 + progress);
    }

    // Dual-fit lookahead — r2 == next item closes the bin on third placement.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 26.0;
        }
    }

    // Mid-band residual consolidation — 26-40 band is a common waste source;
    // when multiple bins fit, prefer the one that escapes this band.
    if fitting_bins_count > 1 && bin_residual < bin_capacity && post_residual > 0 {
        if post_residual >= 26 && post_residual <= 40 {
            score += 10.0;
        } else if post_residual >= 41 {
            score -= 5.0;
        }
    }

    // New-bin threshold refinement — opening a fresh bin is only worth it
    // when the best alternative would strand a large fraction of residual.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_alt = (post_residual as f64).min(mean_residual);
        if best_alt > 20.0 {
            score += (best_alt - 20.0) * 0.6;
        }
    }

    // Perfect-fill anticipation via pair-sum against the full bin.
    if next_item_size > 0 && item_size + next_item_size == bin_capacity {
        score -= 32.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Residuals too small to hold the minimum item (1..10 under the old rule,
    // but sizes go down to 1 here) are only "dead" if they can't fit the
    // lookahead item either. Penalize tiny gaps hard since they waste capacity.
    let gap = post_residual;
    if gap > 0 && gap < 10 {
        score += 25.0; // unusable sliver
    } else if gap >= 10 && gap < 20 {
        score += 6.0;  // marginal gap: only fits very small items
    }

    // Reward tight fits (exact fit is ideal).
    if gap == 0 {
        score -= 40.0;
    } else if gap <= 5 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0; // next placement would create a sliver here
        }
    }

    // --- Open bins pressure ---
    // With many open bins, prefer consolidation into existing bins to avoid
    // spreading residual capacity thinly.
    let open_pressure = open_bins_count as f64 * 0.35;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor
        // (large post_residual waste) or few bins fit.
        score = 60.0
            + (post_residual as f64 * 0.0)
            + if fitting_bins_count == 0 { -50.0 } else { 0.0 }
            + if fitting_bins_count == 1 { 45.0 } else { 0.0 }
            + if next_item_size > 0 && bin_capacity >= item_size + next_item_size { -20.0 } else { 0.0 };
        // Slight stream-position drift: early on, be a bit more willing to open.
        score -= 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // Fewer open bins relative to mean residual -> new bin less attractive.
        score += mean_residual * 0.05;
        return score;
    }

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins with residual below the mean (older, emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

